var e={Id_Editor_Unnamed:{en:`Unnamed`,zh:`Unnamed`},Id_Editor_Default:{en:`Default`,zh:`Default`},Id_Editor_AnyLocation:{en:`(Any Location)`,zh:`(Any Location)`},Id_Editor_AnyCharacter:{en:`(Any Character)`,zh:`(Any Character)`},Id_Editor_AnyItem:{en:`(Any Item)`,zh:`(Any Item)`},Id_Editor_AnyEvent:{en:`(Any Event)`,zh:`(Any Event)`},Id_Editor_AnyObject:{en:`(Any Object)`,zh:`(Any Object)`},Id_Editor_None:{en:`(None)`,zh:`(None)`},Id_Scenario_Name:{en:`Every Rose Has Its Thorn`,zh:`玫瑰皆有刺`},Id_Character_Name_0:{en:`Chief Officer Allen`,zh:`阿伦总警官`},Id_DisplayTextPerState_0:{en:`You don't need to know the details of my private life. Get back to your case-- time is running out!`,zh:`你不需要知道我的私生活细节。把握时间破案吧！时间宝贵！`},Id_Location_Name_0:{en:`Police Station`,zh:`警局`},Id_DisplayTextPerState_1:{en:`Yes, what do you want?`,zh:`好吧，你想知道什么？`},Id_Character_Name_1:{en:`Eric Gloomerry`,zh:`艾力·古鲁梅利`},Id_Character_Name_2:{en:`Jeremy King`,zh:`哲礼美·甘`},Id_Character_Name_3:{en:`Harvey Marshall`,zh:`哈维·马绍`},Id_Character_Name_4:{en:`Lou Chin`,zh:`刘紫嫣`},Id_DisplayText_Default_0:{en:`Oh, I'm afraid I don't have a good memory for faces...`,zh:`噢，恐怕我不怎么擅长认出人的样貌。`},Id_DisplayText_Default_1:{en:`I mostly make the dead speak, if you see what I mean...`,zh:`希望你能明白，我的专长是让死人说话。`},Id_DisplayText_Default_2:{en:`I can't find anything on social networks.`,zh:`我在网路上找不到关于这事的资讯。`},Id_DisplayTextPerState_2:{en:`Technology is my thing! What do we have here?`,zh:`科技是我的专长！有什么需要帮忙？`},Id_DisplayTextPerState_3:{en:`The dead don't lie, and they never contradict me. Who is this about?`,zh:`死人不会说谎，对我揭露的都是实话。这次是谁？`},Id_DisplayTextPerState_4:{en:`If I can help you to better understand the intricacies of the human mind, I'd be happy to do so!`,zh:`如果你需要明白错综复杂的人心，我很乐意帮忙。`},Id_DisplayTextPerState_5:{en:`Hello! What do you have for me?`,zh:`幸会，请问有事吗？`},Id_DisplayTextPerState_6:{en:`I can tell you that behind this person's extreme thoroughness hides a highly developed sense of work ethics. Apart from that, I don't know how I can help you.`,zh:`我能告诉你的是这人做事极度认真仔细，心怀高尚的工作操守。除此以外，我不知道还可以帮你什么。`},Id_Character_Name_5:{en:`Nelly Flower`,zh:`奈莉·弗萝娃`},Id_Character_Name_6:{en:`Daisy Austen`,zh:`黛丝·奥斯汀`},Id_Character_Name_7:{en:`Lily Chapman`,zh:`莉莉·察雯`},Id_Character_Name_8:{en:`Jasmine Blue`,zh:`雅仕敏·白露`},Id_Character_Name_9:{en:`Marc Doyle`,zh:`马克·代尔`},Id_Character_Name_10:{en:`John Raider`,zh:`约翰·赖达`},Id_Character_Name_11:{en:`Sean Louis`,zh:`西恩·路易`},Id_Character_Name_12:{en:`William Peare`,zh:`威廉·比亚`},Id_Character_Name_13:{en:`Jodie Green`,zh:`祖迪·葛林`},Id_Character_Name_14:{en:`Mitch Foster`,zh:`密楚·佛斯特`},Id_Character_Name_15:{en:`Mike Damon`,zh:`麦克·戴蒙`},Id_DisplayText_Default_3:{en:`What do you want me to tell you? It's not for me to do your job! Come back when you have enough evidence to charge someone.`,zh:`你要我告诉你什么？你的工作不应该由我来做！快回去搜查，直到找出足够证据起诉任何一个人吧！`},Id_DisplayText_Default_4:{en:`There is no such person at the police station.`,zh:`警局里没有这个人。`},Id_Scenario_Introduction:{en:`<i> Over the last couple of months, fear has gripped young people, and London nights have lost their excitement. A serial killer is running amok. His three known victims are young women from artistic circles.</i>
@Chief officer Allen <char=15> has summoned you to investigate the disappearance of a possible fourth victim: twenty-something-year-old Nelly Flower <char=03>. @In these cases, speed is needed. Come and press charges as soon as you have an idea of who did it.`,zh:`<i>过去几个月，伦敦入夜之后人人自危。一名连环杀手肆意行凶，新闻报导说三名受害人都是年轻女子。</i>

@阿伦总警官<char=15>委派你调查一名失踪女子——二十多岁的奈莉·弗萝娃<char=03>，怀疑她是第四名受害人。@这起案子需要你分秒必争。一旦你发现犯人，便必须马上汇报。`},Id_DisplayTextPerState_7:{en:`<i>Nelly Flower... Her disappearance is alarming. It's been three days since she left her Lewisham studio <loc=J>.</i>`,zh:`<i>奈莉·弗萝娃……她离开路易咸的工作室<loc=J>以来已经三天了，音讯全无。</i>`},Id_DisplayTextPerState_8:{en:`She is a 23-year-old woman. Her disappearance is worrying, especially with that killer at large in the area. She hasn't shown up for 3 days at her modeling agency, a small place located in Camden Town <loc=E>.`,zh:`她二十三岁，失踪一事令人担忧，尤其是连环杀手也在那区域触摸。康登镇里，她所属模特儿经纪公司的小小办公室<loc=E>，已经有三天没有见过她露面。`},Id_DisplayTextPerState_9:{en:`Bring her body to me so I can understand what happened to her.`,zh:`给我把尸体带来，我才能知道发生什么事。`},Id_DisplayTextPerState_10:{en:`Based on her lifestyle and habits, she is a very focused young woman who is emotionally involved in her roles, and will stop at nothing to achieve whatever ambitions she may have.`,zh:`根据她的生活习惯，她是名十分专注的年轻女性，对于自己的身份角色容易掀起情绪波动，而且达成目标之前不会停下脚步。`},Id_DisplayText_Default_5:{en:`I don't know who this is.`,zh:`我不认识这人。`},Id_DisplayTextPerState_11:{en:`Nelly, missing? But that's awful! We did so many projects together... You think it has something to do with the killer of young women? Do Lily <char=02>and Jasmine <char=20>know about this?`,zh:`奈莉失踪了？真可怕！我们一同工作过很多次……你认为跟年轻女性的连环杀手有关吗？莉莉<char=02>和雅仕敏<char=20>知道这事吗？`},Id_DisplayText_Default_6:{en:`I may be well known for my talents, but I don't know all my fans.`,zh:`我固然天生丽质，但也无法记得每一位粉丝。`},Id_DisplayTextPerState_12:{en:`Nelly? Oh my God... So that's why John <char=31> and I haven't seen her at rehearsals in Bloomsbury <loc=L>... I hope nothing bad happened to her!`,zh:`奈莉？我的天……难怪约翰<char=31>和我这几天都没看到她来布鲁姆斯伯里<loc=L>这里彩排……希望她一切平安！`},Id_DisplayText_Default_7:{en:`If you ask me, this person should not apply to work as a model. It's a ruthless world, you know...`,zh:`要我说的话，我不认为这人应该做模特儿。你要知道这行可不容易……`},Id_DisplayTextPerState_13:{en:`Poor Nelly, how tragic... Did you inform our agent Mike Damon <char=55>? We both worked in a modelling agency in Camden Town <loc=E>.`,zh:`可怜的奈莉……你告诉了麦克·戴蒙<char=55>了吗？我跟奈莉都隶属康登镇一家模特儿经纪公司<loc=E>。`},Id_DisplayText_Default_8:{en:`Who is this?`,zh:`他是谁？`},Id_DisplayTextPerState_14:{en:`Yeah... I am the one who reported her missing, she's my girlfriend. I hadn't seen her in three days and it's unusual for her not to pester, erm, call me regularly.`,zh:`对，是我报案说她失踪了。她是我的女朋友，而我有三天没见过她了。平常她有够烦……嗯我是说经常打电话给我。`},Id_DisplayText_Default_9:{en:`I don't know who this person is.`,zh:`我不认识这人。`},Id_DisplayTextPerState_15:{en:`That can't be true! I knew it was strange for her to bail out on us like that. I thought she was brilliant, but our director <char=42> definitely didn't, and would have killed her more than once during rehearsals!`,zh:`这不是真的！我就纳闷为什么突然找不到人。我认为她十分优秀，但导演<char=42>不这么想，他在彩排期间大概在心里杀死她不只一次了。`},Id_DisplayText_Default_10:{en:`I would like to help you but I don't know that person.`,zh:`我很乐意帮助你，但我不认识这人。`},Id_DisplayTextPerState_16:{en:`Nelly? She's a knockout who used to attract a whole bunch of disturbed guys, like that bloke <char=32> who followed her to the park where we train <loc=D>. @But she's addicted to my best mate Marc <char=50>- she's completely crazy about him! He told me once that he found her too clingy. `,zh:`奈莉？她很有魅力，经常招蜂引蝶，例如有个小伙子<char=32>，跟踪她到我们练习的公园<loc=D>。@但她迷上了我的好兄弟马克<char=50>！马克曾经跟我埋怨说那女孩太黏人。 `},Id_DisplayText_Default_11:{en:`No, it doesn't mean anything to me.`,zh:`我不认识这人。`},Id_DisplayTextPerState_17:{en:`Let's run away! What you should say is that she couldn't bear the pressure of being the lead actress, and she deliberately ran off to hide her shame in the middle of nowhere! @I will have to find someone else to take over her role. It can only be better. I don't want my masterpiece to be wrecked by amateurs!`,zh:`走开！你应该这样讲，她受不住担纲主演的压力，所以主动退出，在某个我们找不到的地方羞愧地躲起来！@我会找到人选代替她的位置，而这对我们百利无一害。我才不要被新人毁掉我的大作！`},Id_DisplayText_Default_12:{en:`What? Who?`,zh:`什么？谁？`},Id_DisplayTextPerState_18:{en:`I met her a few years ago, before she became a model. You know, getting out of the asylum and kicked out into life brings you closer...`,zh:`几年前我见过她，当时她还没当上模特儿。要知道，离开精神病院重新投入社会需要一点帮助……`},Id_DisplayText_Default_13:{en:`Yeah, so what?`,zh:`哦？所以？`},Id_DisplayTextPerState_19:{en:`Nelly is very pretty and I really wanted to... talk to her, but her boyfriend <char=50> won't let me near her. Wouldn't you want to?`,zh:`奈莉非常漂亮，所以我很想……跟她说话，但她的男朋友<char=50>不让我靠近她。你不也想接近她吗？`},Id_DisplayText_Default_14:{en:`No, this person isn't represented by my agency.`,zh:`这不是本经纪公司的人。`},Id_DisplayTextPerState_20:{en:`This can't be true... Her disappearance is a disaster, I am supposed to introduce her for a major campaign shortly and she was going to be my winner, there's a lot of cash to be made! Have you checked her place in Lewisham<loc=J>?`,zh:`怎么会……她失踪实在是灾难。我还打算推荐她参加即将举行的重要赛事，她一定能夺冠，帮我们赚很多很多钱！你搜查过她在路易咸的家<loc=J>吗？`},Id_DisplayTextPerState_21:{en:`That's my boyfriend. He's handsome, don't you think? But he's too tormented to be a model, so he turned to acting <loc=L>. Nelly <char=03> was his stage partner. They have a rehearsal space in Bloomsbury <loc=L>`,zh:`他是我的男朋友，很英俊对吧。他却认为当模特儿是折磨，所以转向演戏。奈莉<char=03>曾是他的台上拍档，他们在布鲁姆斯伯里有个彩排场<loc=L>。`},Id_DisplayTextPerState_22:{en:`With the girls <char=03><char=02>,<char=20>, I work at the modeling agency, but it's pretty hard to earn a living there. I also have a part-time job at the "Bronze" in Soho <loc=C>. We truly are a family, you know!`,zh:`我跟其他女生<char=03><char=02><char=20>一起在一家模特儿经纪公司工作，但那里的条件可不容易维持生计。我还在苏荷区一家叫「青铜」的酒吧<loc=C>兼职。看！我们真的像一家人。`},Id_DisplayTextPerState_23:{en:`Lily is a model too, but she also has other talents: she works with Nelly <char=03> and John <char=31> on a contemporary theatre project. @They have a rehearsal space in Bloomsbury <loc=L> with Mr Peare <char=42>.`,zh:`莉莉也是模特儿，但除此之外她还有其他天赋——她跟奈莉<char=03>和约翰<char=31>一起演出当代剧。@他们在布鲁姆斯伯里跟比亚先生<char=42>一起有个彩排场<loc=L>。`},Id_DisplayTextPerState_24:{en:`Jasmine is also a model, member of our team of four with Nelly <char=03>, Lily <char=02> and me! She is single. Do you think the killer could also be attracted to her?`,zh:`雅仕敏也是一名模特儿，跟奈莉<char=03>、莉莉<char=02>还有我属于同一个团体！她还是单身，你认为是因为凶手看上她吗？`},Id_DisplayTextPerState_25:{en:`This is Nelly's boyfriend <char=03>. Good looking, isn't he? I went out with him while they were already together, but it was just a fling. It has to be said that she was giving him a hard time and he needed support... But don't tell John <char=31> about it!`,zh:`他是奈莉<char=03>的男朋友。很帅对吧。两人开始交往以来，我也曾经跟他一起出外，但只是一时冲动。当时他说奈莉让他难受，所以需要一点支持……这事别告诉约翰<char=31>！`},Id_DisplayTextPerState_26:{en:`That's Lily's<char=02> boyfriend, a sportsman with a promising future! But penniless. If only he could get a university scholarship from his athletic skills...`,zh:`他是莉莉<char=02>的男朋友，前景光明的运动员！但现在很穷，希望他能以运动天赋赢得大学奖学金……`},Id_DisplayTextPerState_27:{en:`I don't really know him. But he should focus his play on the serial killer, it would be a success!`,zh:`我不认识他，不过要是他以最近的连环杀人犯来创作剧作，一定大受欢迎！`},Id_DisplayTextPerState_28:{en:`Erm... I don't know who this is...`,zh:`嗯……我不清楚。`},Id_DisplayTextPerState_29:{en:`Don't you find he looks unstable? What if he was the serial killer in the end?`,zh:`你不觉得他怪怪的吗？会不会就是连环杀手？`},Id_DisplayTextPerState_30:{en:`That's our boss! He may not look too welcoming, but he finds good contracts for us. At the moment the four of us are applying for the same campaign.  @Nelly <char=03> and Jasmine <char=20> are the favorites. There is a lot of money waiting for the one who gets selected.`,zh:`他是我们的老板，看上去不那么和善，不过为我们找到很好的工作合约。目前我们四人都报名参加了同一个甄选比赛。@奈莉<char=03>和雅仕敏<char=20>胜算最大。胜出的奖金可丰厚了！`},Id_DisplayTextPerState_31:{en:`A strange young woman... Her words suggest a particular inclination towards hybristophilia, which is a fascination and, indeed, a strong attraction towards criminals.`,zh:`奇怪的年轻女人……她的言行透露她有恋罪癖，就是崇拜甚至爱慕罪犯。`},Id_Location_Name_1:{en:`The Bronze`,zh:`青铜酒吧`},Id_Location_Name_2:{en:`Modeling Agency`,zh:`模特儿经纪公司`},Id_Location_Name_3:{en:`The Victim's Studio`,zh:`死者的工作室`},Id_Location_Name_4:{en:`Rehearsal Space`,zh:`彩排场`},Id_Location_Name_5:{en:`Sports Field`,zh:`运动场`},Id_Location_Name_6:{en:`Squat`,zh:`非法占用居所`},Id_DisplayTextPerState_32:{en:`Daisy is a nice girl, though a bit troubled by that serial killer roaming around... It's almost an obsession for her!`,zh:`黛丝是个好女孩，不过很担忧最近沸沸扬扬的连环杀手……担心得像是着了魔！`},Id_DisplayTextPerState_33:{en:`What do you want to know? I am beautiful, brilliant and an even better actress than Nelly <char=03> ! Don't hesitate to come and see me at rehearsals on our stage in Bloomsbury <loc=L>. @I just need my talent to be fully recognized so I can stop working as a waitress to make extra money.`,zh:`你想知道什么？我才貌兼备，演技比奈莉<char=03>更优秀！来布鲁姆斯伯里<loc=L>看我的舞台彩排吧。@等到有人发掘我的才华，我就不用再做服务生赚外快了。`},Id_DisplayTextPerState_34:{en:`It can be said that this young woman is very aware of her value and won't let any obstacle stand in her way to glory.`,zh:`可以这么说，这名年轻女子很自负自己的价值，不会让任何障碍阻止她成功。`},Id_DisplayTextPerState_35:{en:`With Jasmine, we used to be a lovely team of four at the agency. She is a fierce candidate when it comes to the campaign we are applying for at the agency. A little too fierce indeed... My Sean <char=45> had better not set eyes on her!`,zh:`我在经纪公司跟雅仕敏一起同属一个四人组合，那时候轻松多了。不过经纪公司为我们报名参加一个甄选后，她就显得很进取……有点太进取了。希望我亲爱的西恩<char=45>不要太关心她！`},Id_DisplayTextPerState_36:{en:`That's Nelly's <char=03> boyfriend. A real hunk! There was a time when we flirted a bit with each other. I was wearing my femme fatale outfit to rehearse a role and... well, my attempt succeeded beyond my wildest expectations.`,zh:`他是奈莉<char=03>的男朋友，十分健壮迷人！有一次我们互相调了一下情，当时是在彩排，我穿著美艳诱人的戏服，然后……后果狂野得超乎想像。`},Id_DisplayTextPerState_37:{en:`That's Daisy's <char=05> boyfriend. A passionate guy, who helps his stage partners to better themselves. He is headlining with Nelly <char=03> while I only had a supporting role. `,zh:`他是黛丝<char=05>的男朋友。非常热情，帮助我的舞台伙伴提升自己。他跟奈莉<char=03>一同领衔主演，而我只演出配角。`},Id_DisplayTextPerState_38:{en:`That's my man! He talks to me about his adventures. He also works here at the Bronze, at least he will until his sporting skills get recognized. He would need more money to pursue his dream.`,zh:`他是我的男朋友！不时跟我聊起他的冒险事迹。他需要钱去追梦，所以也在这家店工作，起码要到自己的运动才华得到认可才会离开。`},Id_DisplayTextPerState_39:{en:`This is our director, who coaches us. The play he's created is intense. It's the story of a man on the verge of madness, who will do anything to keep his conquests close to him and who can't stand being abandoned.`,zh:`他是我们的总监和教练。他创作的剧目很尖锐，讲述频临疯狂的男人，为了成功不择手段，不能忍受默默无闻。`},Id_DisplayTextPerState_40:{en:`That's our agent. An efficient guy who managed to register the four of us <char=03><char=05>,<char=02>,<char=20> into the casting call for a famous brand. The stakes are very high, our career would take off immediately.`,zh:`他是我们的经纪人，办事很有才干，管理我们四个人<char=03><char=05><char=02><char=20>，目前一同参加著名品牌的甄选。这是重大机会，我们的事业随时会起飞。`},Id_DisplayTextPerState_41:{en:`That's one of the contestants for the casting. I like her but she will never make it. Did you know that she was taking drugs to suppress her appetite? I saw a shady girl <char=54> supplying her in secret.`,zh:`她也参加了甄选，我喜欢她，但她未必能成功。你知道她吃药抑制食量吗？我见过有个阴沉的女孩<char=54>暗中给她提供药物。`},Id_DisplayTextPerState_42:{en:`Our agent Mike registered our group of friends because we are the ones who usually land most contracts. Especially me, in fact. Lily<char=02> is mostly interested in her theatre <loc=L>. She would do anything to have a lead role, and she rehearses for hours on end in a small theatre in Bloomsbury <loc=L>`,zh:`经纪人麦克认为我们是一群朋友，因为我们接到最多合约。实际上，我的数量最多。莉莉<char=02>对剧场演出兴趣最大，舍得付出一切来担纲主角，在布鲁姆斯伯里一所小剧场<loc=L>日夜排练。`},Id_DisplayTextPerState_43:{en:`Me? I do everything I can to make it in the fashion world. Now that Nelly <char=03> is not around, I have every chance of winning the casting and the handsome amount of money that comes with it. And then: no more worries!`,zh:`我？我舍得付出一切来进入时装界。现在奈莉<char=03>不见了，所以我大有机会胜出甄选，赢得丰厚奖金，那么就能一帆风顺！`},Id_DisplayTextPerState_44:{en:`OK... I have to admit, he does not leave me cold. I love sportsmen. They are so sexy in their jackets... But Marc is Nelly's <char=03> boyfriend, so we only did it once and then I let it go.`,zh:`好吧……我必须承认我对他很有好感。我喜欢运动员，穿上夹克显得非常性感……不过马克是奈莉<char=03>的男朋友，所以我们只做过一次就分开了。`},Id_DisplayTextPerState_45:{en:`Oh, you know acting students...`,zh:`噢，演剧的学生……`},Id_DisplayTextPerState_46:{en:`Erm... How do I say... I would have liked to see him today at practice... I have the feeling that there is trouble brewing between him and Lily <char=02> and that he's attracted to me, so...`,zh:`嗯……怎么说呢？我希望今天看到他，因为感觉他跟莉莉<char=02>之间有些纠纷，而我对他有好感……`},Id_DisplayTextPerState_47:{en:`That's our agent, he makes us work hard. That's good for us, but he is mainly lining his pockets in the process.`,zh:`他是我们的经纪人，督促我们努力工作，固然对我们有益，不过最终他的目的是让财富流进他的口袋。`},Id_DisplayTextPerState_48:{en:`This type of profile is mostly characterized by their monomania: their obsessions are centered on anything that could be useful for their career, at any price.`,zh:`这份资料是典型的偏执心态：全心投入事业，为了成功可以牺牲一切。`},Id_DisplayTextPerState_49:{en:`She is one of Nelly's <char=03> model friends, they work in the same agency... A real tiger, if you see what I mean.`,zh:`她是奈莉<char=03>的模特儿朋友，同属一家经纪公司……她雄心勃勃。`},Id_DisplayTextPerState_50:{en:`A model like my Nelly <char=03>, but much more of a hottie. They also have a theatre project or something like that. Attending rehearsals at the theatre <loc=L>, that's not my thing.`,zh:`跟我亲爱的奈莉<char=03>一样都是模特儿，但更火辣。她们好像一同演剧什么的，不过我不喜欢这种，所以没去过剧场<loc=L>看彩排。`},Id_DisplayTextPerState_51:{en:`Her little Miss Perfection attitude makes her even hotter, if you ask me.@ My mate Sean<char=45> has a crush on her. At the same time, if she's the one who scores the big casting through the agency, she's going to make lots of money... so it would be good for Sean to hook up with her before then.`,zh:`要我评论的话，她追求完美的态度让她看起来更有魅力。@我的好友西恩<char=45>暗恋他。现在她参加了一个甄选，获选的话会赢得巨额奖金……所以西恩应该趁现在示爱了。`},Id_DisplayTextPerState_52:{en:`Cricket is my passion. I have a good team with my mates. It would be nice to turn professional and be paid for it some day.`,zh:`我的热情全都投入在板球上。我的队友都很优秀，而最希望的是某天能进入专业球队，成为职业选手。`},Id_DisplayTextPerState_53:{en:`That face looks familiar... An intellectual or something like that?`,zh:`这人看起来很面熟……是学者之类吗？`},Id_DisplayTextPerState_54:{en:`Yeah, a real mate you can count on! And a good player, but he is too broke. He has to work in bars like the Bronze in Soho<loc=C> to get a bit of extra cash. @Cricket is his true passion, but he doesn't really have time to train with his jobs.`,zh:`对，出事情时能倚靠的死党！而且他球也打得不错，就是太穷。他只有在苏荷区一家叫青铜的酒吧<loc=C>上班，才赚得到一点钱。@他对板球非常有热枕，但是为了工作，腾不出时间练习。`},Id_DisplayTextPerState_55:{en:`Hey wait... Isn't that the weird guy I saw hanging around Nelly <char=03> ?`,zh:`等等……他不就是跟在奈莉<char=03>身边的家伙吗？`},Id_DisplayTextPerState_56:{en:`She is lovely and I love her, but I find her a bit skinny. I am worried about her.`,zh:`她很令人心动，我十分爱她，不过我担心她有点太瘦。`},Id_DisplayTextPerState_57:{en:`If you ask me, he is a rather unstable young man. His behavior is very erratic and shows his overall inconstancy and lack of empathy.`,zh:`你问我的话，他是个比较不稳定的小伙子，做事没规律，躁动不安，而且缺乏同理心。`},Id_DisplayTextPerState_58:{en:`She's a good enough actress but excessively jealous of Nelly <char=03>, a real pest who stops at nothing to get the roles she wants.
Yet she has been missing many rehearsals to work in a bar in Soho, the Bronze <loc=C>.`,zh:`她是一名好演员，但是非常嫉妒奈莉<char=03>，讨厌的虫子，贪婪永无止境，只想把想要的角色拿到手。

不过最近她经常在苏荷区叫青铜的酒吧<loc=C>上班，所以多次没有来排练。`},Id_DisplayTextPerState_59:{en:`I think it is one of Daisy's <char=05> and Nelly's <char=03> model friends. They were talking about forming a group...`,zh:`我想她是黛丝<char=05>和奈莉<char=03>的模特儿朋友，听她们谈过团体组合的事情。`},Id_DisplayTextPerState_60:{en:`Nelly's <char=03> boyfriend, right? He's probably training in Hyde Park <loc=D> with his mate Sean <char=45>. That's the only thing he cares about, she had every right to be jealous!`,zh:`奈莉<char=03>的男朋友吧。他应该常常在海德公园<loc=D>跟好朋友西恩<char=45>练习，这是他唯一关心的事情。我明白奈莉为什么嫉妒！`},Id_DisplayTextPerState_61:{en:`Yes? You know, I am just trying to make a living from my passion: acting is really a way out for me, it allows me to fulfill myself.`,zh:`哦？我只是希望能透过我的热情来谋生。演戏能充分满足我，是我的渴求。`},Id_DisplayTextPerState_62:{en:`Lily's<char=02> boyfriend, impossible not to know about him. But she should be careful: he's a social climber more than anything else...`,zh:`莉莉<char=02>的男朋友，谁不认识他呢？不过莉莉应该小心，这人也许会利用别人往上爬……`},Id_DisplayTextPerState_63:{en:`A good director and an excellent teacher, although dreadfully strict. The character I'm portraying in the play he wrote is particularly complex. @I had to carry out many experiments to step into the shoes of this man who stalks his conquests and leaves roses at their place because he refuses to let them abandon him. Pure genius.`,zh:`好的总监，更是卓越的老师，虽然严厉得要命。我在演出他执笔的戏剧，饰演的角色非常复杂。@我花了很多功夫，尝试理解他的成功之道。他行事不愿降低自己迎合他人，是个不折不扣的天才。`},Id_DisplayTextPerState_64:{en:`I believe he is the girls' agent. I've never met him personally.`,zh:`他是那些女孩的经纪人吧。没跟他见过面。`},Id_DisplayTextPerState_65:{en:`This is a young man who is easily influenced, as his identity is still being built. As an actor, he plays a dangerous role-playing game. To achieve excellence, he tries to experience in reality the emotions felt by his character.`,zh:`这年轻人还在建立自己的人格，很容易受人左右。他入戏的方法很危险，为了演出完美，会尝试将角色的情感带入现实生活中。`},Id_DisplayTextPerState_66:{en:`One of the four girls who participate in the casting. There's a lot of cash at stake for the one who will sign the contract.`,zh:`其中一个参加甄选的模特儿。赢得那份合约的人会赚大钱。`},Id_DisplayTextPerState_67:{en:`Yep, it's my girlfriend! Charming, isn't she? But with all the time she dedicates to acting, I don't think she'll be able to win the casting to land this brand campaign.`,zh:`对，她是我的女朋友，魅力非凡！不过她把时间放在演戏，所以我不觉得她能赢得甄选。`},Id_DisplayTextPerState_68:{en:`I have to say, she doesn't leave me cold, and with Nelly <char=03> missing she is the one with the best chances to land the casting, and the money that goes with it. Better yet, she's ready to share: she's always generous to her loved ones.`,zh:`我必须承认对她很有好感，而且如今奈莉<char=03>失踪了，她是最热门的人选，赢得甄选和丰富奖金。更令人开心的是，她对心爱的人很慷慨。`},Id_DisplayTextPerState_69:{en:`That's my mate! We're a strong cricket team. I'd love to have more time and the means to get out there and turn professional... @We already got the burgundy jackets with the name of our team, the Bats n' Roses. Not a bad start, is it?`,zh:`他是我的死党！我们同属一支超屌的板球队，而我很乐意付出更多时闲，找到办法晋身专业球员……我们已经拿到酒红色夹克，上面有队伍名字——蝙蝠与玫瑰。还不赖吧。`},Id_DisplayTextPerState_70:{en:`I don't know him that well. He's not a sportsman. From what I've seen, he looks a bit nutty.`,zh:`我跟他不熟。他不是运动员，看起来像个傻瓜。`},Id_DisplayTextPerState_71:{en:`It's true that I have to work several shifts to get by. I am afraid that my performance on the pitch might suffer.`,zh:`没错，我花了很多时间上班，我担心球技因此退步。`},Id_DisplayTextPerState_72:{en:`That strange guy keeps hanging around the park. I don't like the way he looks at our girlfriends.`,zh:`这怪人常常到这公园附近蹓跶，我不喜欢他看我女朋友的视线。`},Id_DisplayTextPerState_73:{en:`She is at least as haughty and full of herself as Nelly <char=03> ! But I don't really have a choice, as I can't afford to pay real actresses yet. @ This one should dedicate herself more to acting instead of doing who knows what in that Soho bar <loc=C>, the Bronze I believe it's called...`,zh:`她跟奈莉<char=03>相比，傲慢与自负有过之而无不及！不过我没得选，因为我还聘不起专业的演员。@这人应该投入更多时间在演戏，而不是浪费在苏荷区的酒吧<loc=C>，我记得名字叫青铜……`},Id_DisplayTextPerState_74:{en:`A serious young man, who is very passionate about his role. He will do anything to get inside his character. Even though I am not a fan of the Actor's Studio method, I appreciate his absolute commitment.`,zh:`认真的小伙子，非常投入地演戏，而且无时无刻揣摩自己的角色。虽然我自己不会用这样的方法演绎，不过很欣赏他这种态度。`},Id_DisplayTextPerState_75:{en:`You are interested in my current play? It's a story of drama and passion with at its heart the obsession of a man - the man with the rose - for the women he pursues with his affection because he can't bear to be left by them.`,zh:`你有兴趣知道我正在上演的剧作吗？那是关於戏剧和热情的故事，讲述一名男子——玫瑰男——全心全意、疯狂追求一些女子，忍受不了被她们丢下，以至着魔的情节。`},Id_DisplayTextPerState_76:{en:`I don't like that person. Ask him why he ended up like this, and you should learn a thing or two...`,zh:`我不喜欢这人。问问他为什么事情变成这样，你应该能从中吸取教训……`},Id_DisplayTextPerState_77:{en:`In fact, she asked me to cover for her. That's why I let her into the squat at night and I didn't say anything. She looked like she was feeling so bad! In memory of the time we spent together at the asylum, I had to at least help her.`,zh:`事实上她曾经请我保密，所以晚上我让她进去非法占用居所，而且对任何人也没有谈起。她看来深受打击！想起在精神病院一起度过的时光，我觉得应该帮助她。`},Id_DisplayTextPerState_78:{en:`I know her! She bought some speed from me to suppress her appetite, so she could keep her figure for castings and stuff.`,zh:`我认识她！她向我买了一些药物抑制食欲，用以保持身形参加甄选等等。`},Id_DisplayTextPerState_79:{en:`That's Nelly's <char=03> boyfriend! I see him from time to time, he likes to party and I supply him with what he needs to make the party longer and wilder.`,zh:`他是奈莉<char=03>的男朋友！我不时见到他，他喜欢开派对，因此我为他提供需要的东西，让派对更久更狂。`},Id_DisplayTextPerState_80:{en:`Me? I am nobody. I do what I can to get by, if you see what I mean. But I don't have any bad intentions, I don't hurt anyone.`,zh:`我？我只是默默无名的人，我只是做点小买卖求生，希望你明白，我并非居心不良，我不会伤害任何人。`},Id_DisplayTextPerState_81:{en:`I already saw him hanging out at the square<loc=D>. I have the feeling he envies the guys who train there and how they have girlfriends He sends chills down my spine!`,zh:`我早已看到他在广场<loc=D>附近闲逛，感觉他在眼红里面正在训练的男子，尤其是眼红他们交到女朋友。看到他便毛骨悚然。`},Id_DisplayTextPerState_82:{en:`One of Nelly's <char=03> friends. But she wasn't as pretty.`,zh:`奈莉<char=03>其中一名朋友，但不算很漂亮。`},Id_DisplayTextPerState_83:{en:`She is also a model. She used to work with Nelly <char=03> on a theatre play in premises in Bloomsbury <loc=L>.`,zh:`她也是模特儿，以前跟奈莉<char=03>一起在布鲁姆斯伯里的小剧场<loc=L>演戏。`},Id_DisplayTextPerState_84:{en:`That's a pretty prize! Will you introduce her to me?`,zh:`她是个美女！你会把她介绍给我吗？`},Id_DisplayTextPerState_85:{en:`Nelly's <char=03> boyfriend. A bloke who doesn't deserve her, if you ask me. He spends his time at the park <loc=D> hanging around other girls. @If I had a jewel like her, I would keep her with me all the time like the treasure she is, and I would make her into a queen the world could admire!`,zh:`他是奈莉<char=03>的男朋友，穷光蛋，配不上奈莉。他常常花时间在公园<loc=D>跟其他女生在一起。@要是跟奈莉这样美人胚子交往的是我，就会把她捧在手心呵护，因为她是我心目中无可比拟的女神！`},Id_DisplayTextPerState_86:{en:`I already saw that big oaf. She sells stuff at the park, I am sure of it! I heard she was bumming around in a squat near East End <loc=I>.`,zh:`我知道她，大块头蠢蛋。我肯定她在公园里卖东西！另外听说她在东区有一间非法占用居所<loc=I>，她经常在那里流连。`},Id_DisplayTextPerState_87:{en:`So what? I just wanted Nelly <char=03> to understand that I am meant for her. I am a romantic! I was here to give her a rose when you showed up!`,zh:`怎么了？我只是想让奈莉<char=03>知道我多么爱慕她！。我是个浪漫的人！你看，我只是想送她玫瑰！`},Id_DisplayTextPerState_88:{en:`A promising girl. With Nelly <char=03>, Lily <char=02> and Jasmine<char=20>, Daisy is supposed to audition for a very famous brand tomorrow, with fame and fortune at stake for the winner. And for me, too.`,zh:`很动人的女孩子。她跟奈莉<char=03>、莉莉<char=02>跟雅仕敏<char=20>一起，本来应该参加著名演艺公司在明天举办的甄选，冠军可以获得可观的名声与财富。当然我也有份。`},Id_DisplayTextPerState_89:{en:`She should try to be less of a diva at that small theatre in Bloomsbury <loc=L> and focus more on her career, if she wants to get ahead.`,zh:`她应该少花点时间在布鲁姆斯伯里的小剧场<loc=L>，专心在真正的事业，才可以向前迈进。`},Id_DisplayTextPerState_90:{en:`One of my favorite, along with Nelly <char=03>. If Nelly is really missing, I think she has every chance to win the casting.`,zh:`我最看重的女生就是她和奈莉<char=03>。如果奈莉真的失踪了，她就最有望赢得甄选。`},Id_DisplayTextPerState_91:{en:`What about my face? What's wrong with my face? You don't like the look of me? It's just the reminder of an old rivalry for a woman, that's all you need to know.`,zh:`我的脸上有什么吗？脸上有什么吗？你不喜欢我的样子？你只需要知道那是我以前跟女性争执的疤痕。此外无可奉告。`},Id_DisplayTextPerState_92:{en:`An arrogant guy who really thinks he is somebody and makes great promises to the young actresses in my agency, and leads them away from their original goal. That's all there is to say about him.`,zh:`高傲的家伙，自以为是，对我公司的年轻女演员许下好高骛远的承诺，带她们远离本该追求的目标。关于他没什么好谈的。`},Id_DisplayTextPerState_93:{en:`The typical sportsman, frustrated not to be recognized in his area of excellence, with no scruples whatsoever when it comes to achieving his goals.`,zh:`典型的运动员，怀才不遇所以沮丧，愿意不惜一切抓住机会。`},Id_DisplayTextPerState_94:{en:`A particularly inspired and tormented man ready to do anything to serve his art.`,zh:`这男人才华出众，同时因此感到很痛苦，并准备为艺术奉献自己。`},Id_DisplayTextPerState_95:{en:`An elusive and rather enigmatic young woman. Typical of people who come from the street and use little tricks to get by. @While doing some research, I found out that she and Nelly stayed at the same psychiatric asylum over the same period. @Doctors say that their friendship was a significant factor in their healing process.`,zh:`畏缩又难以捉摸的年轻女生，是那种会在街上遇到，用点小手段谋生的人。@搜查之后发现她跟奈莉曾经同在一所精神病院。@医生指出两人的友情大大地有助她们康复。`},Id_DisplayTextPerState_96:{en:`What we have here is an antisocial young man with unpredictable reactions, who lives his emotions intensely and has an obsessive tendency.`,zh:`这青年行为难以预测，而且想法十分有害大众，情绪十分激烈，而且似乎因某事而痴迷。`},Id_DisplayTextPerState_97:{en:`Behind his seemingly good nature hides a spiteful and bitter man who was wounded by life. He is totally dedicated to his job at his Camden Town <loc=E> agency.`,zh:`他的动机看似良善，不过本性其实恶毒刻薄。这性格源自以前被伤害的经验，而现在他一心一意投入到康登镇经纪公司<loc=E>的事业里。`},Id_DisplayTextPerState_98:{en:`Yes, how can I help you? Hurry, I am in the middle of my shift!`,zh:`有何贵干？快，我在上班！`},Id_DisplayTextPerState_99:{en:`Hello! I am all yours but hurry up, my shift at another restaurant is about to start.`,zh:`你好！我乐意帮你，可是请尽快，我差不多要到另一间餐厅开始上班。`},Id_DisplayTextPerState_100:{en:`Mike Damon, agent of future star models! What is this about?`,zh:`我叫麦克·戴蒙，未来明星模特儿的经纪人。有何贵干？`},Id_DisplayTextPerState_101:{en:`Yes? I have to rework my portfolio but I can take a few minutes to help you.`,zh:`什么事？我要整理个人档案，但跟你聊个几分钟倒没问题。`},Id_DisplayTextPerState_102:{en:`Hey, let go of my arm! You're hurting me! I didn't do anything, so what!`,zh:`喂，放开我的手！你伤到我了！我什么也没做，干嘛？`},Id_DisplayTextPerState_103:{en:`Oh no, I could feel inspiration coming on! Pfff... it's gone. So how can I help you?`,zh:`嘿！我感到灵感要来了……唉…又走了。那么你找我什么事？`},Id_DisplayTextPerState_104:{en:`Mr Peare, manager of this theatre, author and director. What is this about?`,zh:`我姓比亚，这所剧场的经理、作家及总监。什么事？`},Id_DisplayTextPerState_105:{en:`Just let me drink a little to rehydrate... Okay, how can I help you?`,zh:`让我喝一口来补充水分……好了，有什么事吗？`},Id_DisplayTextPerState_106:{en:`Have you seen our cricket team? They seriously rooock! I am here to support them but maybe I can help you.`,zh:`你看过我们的板球队吗？那真是太~~~~棒了！我来这里为他们打气的，不过也许能帮你。`},Id_DisplayTextPerState_107:{en:`Erm... yes... I... erm... What?`,zh:`嗯……对……嗯……什么？`},Id_DisplayText_Action_0:{en:`<i> You are receiving a phone call from the Police Station.</i> 

Hello? What on earth are you doing? The killer with the rose has just been arrested by another one of my teams, and he's at the Police Station! @Have you found Nelly Flower <char=03>? Hurry up, out of respect for the family and so you don't make fools out of yourselves!`,zh:`<i>你接到警局来电。</i>

喂，你在搞什么鬼？玫瑰杀手刚才已被另一人抓到，带到警局这里了！@你找到奈莉·弗萝娃<char=03>了吗？快，为了她的家人，你最好快点破案，别像个笨蛋在瞎忙！`},Id_DisplayText_Action_1:{en:`<i> The Police Station is calling you.</i>
What the hell are you up to?  We've just been informed of Daisy Austen's <char=05> murder at the modeling agency in Camden Town <loc=E>!@ It's clearly connected to your case, so come back to the police station with a plausible suspect as soon as you can before there are any further victims.`,zh:`<i>你接到警局来电。</i>

老天！你到底做了些什么？有人报案说黛丝·奥斯汀<char=05>在康登镇的模特儿经纪公司<loc=E>被谋杀了！@很明显这跟你的案件有关，所以一旦有头绪知道谁是凶手，便马上回来报告，以免出现更多受害者。`},Id_LocationState_Introduction_0:{en:`You reach the crime scene and discover the new victim's identity: Daisy Austen<char=05>.`,zh:`你来到案发现场，发现新的死者叫黛丝·奥斯汀<char=05>。`},Id_DisplayText_Action_2:{en:`<i> You are receiving a phone call from the Police Station.</i> 

@What's going on? Lily Chapman <char=02> has been murdered in her home in the same manner as Daisy Austen <char=05>! @A team is on site in Soho <loc=C> and found a sports jacket <itm=06> at the scene. @I need your report with a plausible theory soon, before there's another victim!`,zh:`<i>你接到警局来电。</i>

@说明一下你在做什么！继黛丝·奥斯汀<char=05>之后，莉莉·察雯<char=02>在家里也被人发现以相同方式谋杀了！@有一队人已经到了苏荷区<loc=C>，在现场发现一件运动夹克<itm=06>。@你必须尽快找出凶手，以免再有人受害。`},Id_Item_Name_0:{en:`Burgundy jacket`,zh:`酒红色夹克`},Id_Ending_Final_Solution_Text_0:{en:`Nelly Flower is a very disturbed and jealous young woman. She couldn't bear her boyfriend Marc seducing her best friends, and she swore she would get her revenge and make them suffer. @So one by one, she's attempting to kill the girls he flirted with and who dared betray her friendship. To that end, she staged her own kidnapping. @She even went as far as cutting off her own ring finger and leaving a rose at the crime scene to imitate the serial killer who was then attacking in London. She also wore her boyfriend's sports team jacket to conceal her identity, and strangles her victims with a rope she stole at the theatre. @But now that the killer has been arrested, the noose is tightening and she cannot hope to escape your thorough investigation. Well done!`,zh:`奈莉·弗萝娃是个精神不稳定且妒性极强的年轻女性。她受不了男友马克挑逗她的好朋友，发誓复仇，使她们获得惩罚。@所以她决定逐一杀害跟马克有关系的女生，以报复她们背叛友情。首先，她假装自己被绑架，@甚至割掉自己的无名指，并在案发现场留下一朵玫瑰，假装是伦敦连环杀手犯案。同时穿上男友的运动夹克隐藏身份，在剧场偷走一根绳子勒死受害者。@不过经过你严密调查，现在她已经被捕，不能再杀人了。做得好！`},Id_Ending_Question_WrongMandatory_0:{en:`Your case does not hold up, so there must be something you missed. Get back in the field.`,zh:`你的案子还不能解释，一定是漏掉什么事情了。回去继续搜查吧。`},Id_Ending_Question_0:{en:`Who is responsible for Nelly Flower's <char=03> disappearance?`,zh:`谁导致奈莉·弗萝娃<char=03>失踪？`},Id_Ending_Question_1:{en:`Who is the murderer in this case?`,zh:`谁是本案凶手？`},Id_Ending_Question_2:{en:`Why have the girls been killed?`,zh:`为什么女生被杀？`},Id_Ending_Question_3:{en:`What element allowed the copycat to pose as the killer?`,zh:`什么事情让凶手模仿连环杀手？`},Id_Ending_Question_4:{en:`How were the girls killed?`,zh:`女生怎样被杀？`},Id_Ending_FinalSummary_0:{en:`Congratulations, after three unfortunate deaths, you have solved the case!
`,zh:`恭喜，出现三名无辜的死者之后，你终于破案！`},Id_Ending_Final_Solution_Text_1:{en:`Nelly Flower is a very disturbed and jealous young woman. She couldn't bear her boyfriend Marc seducing her best friends, and she swore she would get her revenge and make them suffer. @So one by one, she's attempting to kill the girls he flirted with and who dared betray her friendship. To that end, she staged her own kidnapping. @She even went as far as cutting off her own ring finger and leaving a rose at the crime scene to imitate the serial killer who was then attacking in London. She also wore her boyfriend's sports team jacket to conceal her identity, and strangles her victims with a rope she stole at the theatre. @But now that the killer has been arrested, the noose is tightening and she cannot hope to escape your thorough investigation. Well done!`,zh:`奈莉·弗萝娃是个精神不稳定且妒性极强的年轻女性。她受不了男友马克挑逗她的好朋友，发誓复仇，使她们获得惩罚。@所以她决定逐一杀害跟马克有关系的女生，以报复她们背叛友情。首先，她假装自己被绑架，@甚至割掉自己的无名指，并在案发现场留下一朵玫瑰，假装是伦敦连环杀手犯案。同时穿上男友的运动夹克隐藏身份，在剧场偷走一根绳子勒死目标。@不过经过你严密调查，现在她已经被捕，不能再杀人了。做得好！`},Id_Ending_FinalSummary_1:{en:`The killer hasn't been arrested. Three young women are dead. You haven't found the culprit. How long will this hell go on?
`,zh:`你还未能逮捕凶手。死掉了三名年轻女性，而你还抓不到凶手？你还他妈的要多久？
`},Id_Item_Name_1:{en:`Papers`,zh:`纸张`},Id_Item_Name_2:{en:`Drugs`,zh:`药物`},Id_Item_Name_3:{en:`Bloody finger`,zh:`血淋淋的手指`},Id_Item_Name_4:{en:`Posters and decorations`,zh:`海报及装饰`},Id_Item_Name_5:{en:`Costume jewelery`,zh:`服装珠宝`},Id_Item_Name_6:{en:`Furniture`,zh:`家具`},Id_Item_Name_7:{en:`Daisy's mobile phone`,zh:`黛丝的手提电话`},Id_Item_Name_8:{en:`Piece of rope`,zh:`一条绳子`},Id_Item_Name_9:{en:`Nelly's computer`,zh:`奈莉的电脑`},Id_Item_Name_11:{en:`Tableware`,zh:`餐具`},Id_Item_Name_12:{en:`Kitchen knife`,zh:`厨房刀`},Id_Item_Name_13:{en:`Newspapers`,zh:`报纸`},Id_Item_Name_14:{en:`Office materials`,zh:`办公室用品`},Id_Item_Name_15:{en:`Bedding`,zh:`寝具`},Id_Item_Name_16:{en:`Clothes`,zh:`衣服`},Id_Item_Name_17:{en:`Nelly's bag`,zh:`奈莉的袋子`},Id_Item_Name_18:{en:`Rose`,zh:`玫瑰`},Id_DisplayText_Default_16:{en:`There is no object from this category here.`,zh:`这里没有物品符合这个类别。`},Id_DisplayTextPerState_108:{en:`On the floor, you find a long, slender finger in the carpet pile.`,zh:`你在地毯上发现一根修长的手指。`},Id_DisplayTextPerState_109:{en:`You find posters promoting a production of the musical <i>Fame</i> with Nelly <char=03> and other girls <char=05>,<char=02>,<char=20>.`,zh:`你发现一张海报，宣传音乐剧<i>名扬四海</i>，上面有奈莉<char=03>还有其他女生<char=05><char=02><char=20>。`},Id_DisplayTextPerState_110:{en:`Various pieces of jewelry sit on the small dressing table. They are costume jewels, modern but cheap.`,zh:`小小的梳妆台上有许多珠宝，都是服装道具，时尚但便宜。`},Id_DisplayTextPerState_111:{en:`A table, a dressing table, a cupboard. The typical minimalist furnishings of a model who just moved in on her own.`,zh:`一张桌子、一张梳妆台、一个橱柜，刚刚独自一人搬进城里住的模特儿，典型的极简主义家具。`},Id_DisplayTextPerState_112:{en:`There are still some dirty dishes in the sink. The victim didn't have time to take care of them before she was kidnapped.`,zh:`碟子上还有些污迹，受害人被绑架前，没有时间打理它们。`},Id_DisplayTextPerState_113:{en:`There are a few theatre books, along with neatly organized newspaper clippings about the killer with the rose.`,zh:`有几本戏剧书，旁边有整齐的剪报，都是关于玫瑰杀手的报导。`},Id_DisplayTextPerState_114:{en:`The bed is undone, as if the person had just gotten up.`,zh:`床铺没有铺好，就像睡觉的人刚起床。`},Id_DisplayTextPerState_115:{en:`The cupboard is full of clothes of all styles. It is not surprising that they are all over the place!`,zh:`衣柜里满是各种风格的衣服，到处都是，不过这不值得惊讶。`},Id_DisplayTextPerState_116:{en:`A young woman like her would never had gone out without her handbag. It contains tissues, a moisturizing cream, make-up... and a photo of Mike Damon <char=55> with a woman.`,zh:`年轻女性出门一定会带上手提包。里面有面纸、保湿面霜、化妆品……还有麦克·戴蒙<char=55>与一名女子的照片。`},Id_DisplayTextPerState_117:{en:`There is a yellow rose on the table. That flower is the typical signature of the killer who is currently running amok.`,zh:`桌上有一支黄色玫瑰，是在逃杀手的标志。`},Id_DisplayText_Default_17:{en:`There is no object from this category here.`,zh:`这里没有物品符合这个类别。`},Id_DisplayTextPerState_118:{en:`Various documents: ads, contracts... Nothing holds your attention.`,zh:`很多档案。包括广告、合约。没什么特别的。`},Id_DisplayTextPerState_119:{en:`Close to the victim's body, you find a strange bag full of pills. Drugs, probably.`,zh:`走近尸体，你发现一袋可疑的丸子，也许是药物。`},Id_DisplayTextPerState_120:{en:`The victim's phone. It's still covered with blood. When you take a closer look, you notice that it is switched off but not broken.`,zh:`死者的电话，上面还有血。拿近看一看，发现它关掉但没有坏掉。`},Id_DisplayTextPerState_121:{en:`There is a 50-cm long piece of rope close to the body.`,zh:`尸体附近有一根50厘米长的绳子。`},Id_DisplayTextPerState_122:{en:`A rather compact laptop, password protected.`,zh:`挺小巧的手提电脑。有密码保护。`},Id_DisplayTextPerState_124:{en:`A knife can be found close to the body. The blade is stained with what looks like fresh blood, and so is her ring finger. `,zh:`这把刀子在尸体不远处，刀刃上沾上了血迹，看来是刚下手的鲜血，还有死者的无名指。`},Id_DisplayTextPerState_126:{en:`Some clothes on a rack, probably there for an upcoming photo shoot.`,zh:`架上有些衣服，应该是拍照时穿的。`},Id_DisplayTextPerState_127:{en:`A rose is laid close to the stiff body. It is the same colour as the victim's dress: yellow.`,zh:`僵硬的尸体旁有一朵玫瑰，跟死者的裙子相同颜色——黄色。`},Id_DisplayTextPerState_128:{en:`This unfortunate young woman died by strangulation not long ago, before her left ring finger was cut off. @Her attacker must have stood behind her and used a cable or a rope to apply the necessary pressure on her throat. Hmm... that's not the <i>modus operandi</i> of the killer with the rose.@ Though it's not the cause of death, I also found traces of amphetamines in her blood.`,zh:`没多久前这名不幸的女子左手无名指被割下，然后被勒死。@袭击者一定是在背后用线或绳往喉咙施压。嗯……这不是玫瑰杀手的<i>惯用手法</i>。@虽然这不是死因，但我在死者的血液检测到安非他命。`},Id_DisplayTextPerState_129:{en:`This unfortunate creature also died by strangulation in the same circumstances as Daisy Austen, and her left ring finger has also been severed. @The death is very recent and reveals some kind of relentlessness, as if the killer was starting to lose their temper.`,zh:`这名不幸的少女跟黛丝·奥斯汀一样被人勒死，左手无名指一样被割下。@死亡时间就是没多久前，而且手法残暴，显示凶手已经失去脾气。`},Id_DisplayTextPerState_130:{en:`Poor young woman... Brutal strangulation, left ring finger violently cut... The same killer seems to have struck again.`,zh:`可怜的少女……粗暴地被勒死，左手无名指还被暴力割下……看来是同一人犯案。`},Id_DisplayTextPerState_131:{en:`It is a male sports jacket, which probably belongs to a cricket team according to the back embroidery. However, there are a few long auburn hairs stuck in the collar...`,zh:`这是一件男装运动夹克，背面的刺绣显示它属于一个板球队。衣领上有几条金啡色长发。`},Id_DisplayText_Default_18:{en:`I really don't see what I can get from this.`,zh:`我不知道能从中知道什么。`},Id_DisplayTextPerState_132:{en:`From the fingerprint, which can be easily identified, it is the left ring finger of Nelly Flower <char=03>.`,zh:`很容易便从指纹判断它是奈莉·弗萝娃<char=03>的左手无名指。`},Id_DisplayTextPerState_133:{en:`These are amphetamine pills, which are often used by young women to lose weight and artificially boost their energy levels.`,zh:`这是安非他命药丸，年轻女性通常用来减重并维持亢奋。`},Id_DisplayTextPerState_134:{en:`These are freshly printed flyers featuring the missing Nelly Flower <char=03> and three other young women. It looks like a promotion for some sort of musical, the sentence "I'm gonna live forever" stands out in particular.`,zh:`这传单刚印制好，焦点是失踪的奈莉·弗萝娃<char=03>和另外三名少女，是一部音乐剧的宣传，尤其突出的是「我将永生」这句标语。`},Id_DisplayTextPerState_135:{en:`Technology is not really my field.`,zh:`科技不是我擅长的。`},Id_DisplayTextPerState_136:{en:`Mmm... Interesting. There are traces of blood on this rope, but I would need some more time to analyze it. I need at least an hour to run the test, come back later to learn more about it.`,zh:`嗯……真有趣。绳上有一些血液，但我要多一点时间分析，测试最少要一个小时，那个时候回来找我，就能告诉你更多事情。`},Id_DisplayTextPerState_137:{en:`The analyses performed on the rope seem to show that the blood traces found belong to the missing person Nelly Flower <char=03>.`,zh:`分析结果显示绳子上的血迹属于失踪的奈莉·弗萝娃<char=03>。`},Id_DisplayTextPerState_138:{en:`It's too soon. I need a little more time.`,zh:`太快了，我需要更多时间。`},Id_DisplayTextPerState_139:{en:`Hacking passwords is not really my field of expertise.`,zh:`破解密码不是我的专长。`},Id_DisplayTextPerState_141:{en:`At first glance, this is the knife that was used to cut Daisy's<char=05> finger. I can confirm that the blood on the blade is hers. There are unfortunately no fingerprints to identify. `,zh:`初步分析，这应该是用来割下黛丝<char=05>的手指。我确认上面是她的血。可惜上面没有指纹可供辨认。 `},Id_DisplayTextPerState_142:{en:`As you can see, these are newspaper articles covering the activities of the killer with the rose, and his modus operandi, how the killer operates. @He has the habit of kidnapping young women from artistic circles and leaving behind only one finger and a rose. @Then the body is always mysteriously left at the scene of the kidnapping two days later.`,zh:`如你所见，这些报纸都报导了玫瑰杀手的消息和他的惯用手法。@他习惯绑架艺术圈的少女，在现场只留下一只手指和一支玫瑰。@两天之后，案发现场便会找到失踪者的尸体。`},Id_DisplayTextPerState_143:{en:`This picture was taken in the time of film photography! Considering the color fading and paper aging, it seems to be at least twenty years old.`,zh:`这一张照片是用底片冲洗出来的！从褪色情况推断，这照片已经有最少二十年历史。`},Id_DisplayTextPerState_144:{en:`This is a yellow-colored rose of no particular distinction. The killer with the rose usually leaves a white rose, but this detail never appeared in the press.`,zh:`这是一支黄色玫瑰，上面没有特征。玫瑰杀手通常留下的是白色玫瑰，不过新闻没有报导这细节。`},Id_DisplayTextPerState_145:{en:`The m.o. of the killer is always the same: he stalks a young woman who works in the artistic community and kidnaps her, leaving behind only one finger and a white rose. @The body is then left at the scene of the kidnapping two days later. It is a serial killer: he is not related to his victims and the murders are repeated regularly over time.`,zh:`玫瑰杀手的犯案方式都是这样的：他先跟踪艺术圈的少女，绑架她，在现场留下一根手指和一支白玫瑰。@两天之后，在绑架案发现场便会找到受害者的尸体。那是连环杀人犯，并不认识死者，而且过了一段时间便会犯案一次。`},Id_DisplayTextPerState_146:{en:`The couple in this picture seems to be intimate.`,zh:`这对情侣看来很亲密。`},Id_DisplayText_Default_19:{en:`The analysis of such ordinary objects does not fall within my field.`,zh:`分析物件并非我的长处。`},Id_DisplayTextPerState_147:{en:`Search engines show that she landed many small roles and she appears in smaller advertising campaigns. @She is trying to create a buzz online by promoting a musical with three other girls <char=05>,<char=02>,<char=20>, yet another production of <i>Fame</i>...`,zh:`网路搜寻结果显示她饰演过许多小角色，也出现过在许多小型广告。@最近的动态是不断宣传<i>名扬四海</i>这部音乐剧，试图在网上炒红自己。该剧还有三名女生<char=05><char=02><char=20>一同演出。`},Id_DisplayTextPerState_148:{en:`She is not particularly noteworthy... What mostly stands out on search engines is her taking part in an upcoming production of <i>Fame</i> with three other models<char=03>,<char=02>,<char=20>. `,zh:`她并不出众……搜寻结果显示到最多的是她将会跟其他三名模特儿<char=03><char=02><char=20>一同演出音乐剧<i>名扬四海</i>。 `},Id_DisplayTextPerState_149:{en:`She keeps landing small roles at the theatre, but doesn't always get good reviews. What mostly stands out on search engines is her taking part in an upcoming production of <i>Fame</i> with three other models<char=05>,<char=03>,<char=20>. `,zh:`她不断在剧场演出小角色，不过评论时好时坏。搜寻结果显示最多的是她将会跟其他三名模特儿<char=05><char=03><char=20>一同演出音乐剧<i>名扬四海</i>。 `},Id_DisplayTextPerState_150:{en:`She appears in quite a few advertisements. However, what mostly stands out on search engines is her taking part in an upcoming production of <i>Fame</i> with three other models<char=05>,<char=02>,<char=03>. `,zh:`少数广告里能看到她，不过搜寻结果显示最多的是她将会跟其他三名模特儿<char=05><char=02><char=03>一同演出音乐剧<i>名扬四海</i>。 `},Id_DisplayText_Default_20:{en:`I am not sure you should contact me about this.`,zh:`这事你不应该问我。`},Id_DisplayTextPerState_151:{en:`Interesting... I found deleted messages. It looks like she was anonymously blackmailing Nelly <char=03> about a time in her past when she was in a psychiatric asylum.@ But no matter how much I search the Internet, I can't find anything more about it. Bloody medical confidentiality.`,zh:`有趣……我找到一些被删的讯息，发现原来她知道奈莉<char=03>进过精神病院的历史，并以此勒索。@不过我上网怎么查也找不到这消息。该死的医疗保密。`},Id_DisplayTextPerState_152:{en:`There is a wealth of information here! Someone was blackmailing her, asking her for money to keep quiet about something potentially scandalous in her past that could jeopardize her career.@Furthermore, it looks like Nelly herself was blackmailing her agent Mike Damon <char=55> !`,zh:`这里面有丰富的情报！有人曾经勒索她，声称知道她过去的丑事，要奈莉付遮口费才肯保密。@而且看来奈莉自己也在勒索经纪人麦克·戴蒙<char=55>！`},Id_DisplayText_Default_21:{en:`I mostly make the dead speak, if you see what I mean...`,zh:`希望你能明白，我的专长是让死人说话。`},Id_DisplayText_Default_22:{en:`I am not responsible for lost property.`,zh:`我不负责找失物。`},Id_DisplayText_Default_23:{en:`What do you want me to tell you?`,zh:`我要告诉你什么？`},Id_DisplayTextPerState_154:{en:`Is that the finger cut off by the killer? It's soooo romantic that it's the left ring finger!`,zh:`凶手割下这手指吗？真浪漫！这是左手无名指！`},Id_DisplayTextPerState_155:{en:`Yes, fine, I sometimes take a few pills, but only to keep on top of everything and not overeat. Jodie <char=54> is the one who supplies me. Nelly had put me in touch with her. You won't tell my agent, will you?`,zh:`好吧，有时候我会吃药，目的不过是保持状态，限制我过量进食。药物是祖迪<char=54>给我的。奈莉也跟她有往来。你不会跟我的经纪人说吧。`},Id_DisplayTextPerState_156:{en:`We had a musical project with the girls<char=03>,<char=02>,<char=20>, we were getting ready to do a production of <i>Fame: I'm gonna learn how to fly--high!</i>`,zh:`我们四个女生<char=03><char=02><char=20>会一同演出音乐剧，名叫<i>名扬四海：振翅高飞！</i>`},Id_DisplayTextPerState_157:{en:`That's my phone! Where did you find it?`,zh:`那是我的手机！你在哪里发现的？`},Id_DisplayTextPerState_159:{en:`Yeah, it seems she was getting messages from a person threatening to talk about her past. You knew she had been committed because of her suicidal tendencies? That's enough to wreck a career...`,zh:`对，似乎有人威胁要曝露她的过去。你知道她有点问题，曾有自杀倾向吗？那足以毁掉事业的……`},Id_DisplayTextPerState_160:{en:`What a beautiful collection! I didn't know that Nelly <char=03> was also a fan! Did you know that the killer always leaves a white rose after causing another death? Makes me shiver...`,zh:`真棒的收藏！我都不知道奈莉<char=03>也喜欢这种！你知道杀手总会在杀人后留下一支白玫瑰吗？这真令我激动……`},Id_DisplayTextPerState_161:{en:`Honestly, have you seen the clothes she's wearing in the picture? It must be at least 20 years old!`,zh:`老实说，你看过她照片里穿的衣服吗？最少二十年前了！`},Id_DisplayTextPerState_162:{en:`What a beautiful yellow rose! Is it for me?`,zh:`美丽的黄色玫瑰！送给我的吗？`},Id_DisplayText_Default_24:{en:`So what?`,zh:`所以？`},Id_DisplayTextPerState_163:{en:`It's strange, it looks like the boys' sports jackets. You can find them at the park<loc=D>, that's where they train.`,zh:`奇怪了，看来这是男生的运动夹克。你可以在公园<loc=D>找到这队人。`},Id_DisplayTextPerState_164:{en:`That's not an accessory, it's a real finger! It's dreadful!`,zh:`这不是道具，是真的手指！真可怕！`},Id_DisplayTextPerState_165:{en:`Oh no, I don't touch that stuff! You should ask Daisy<char=05> instead.  `,zh:`我不碰这类东西的！你该问一下黛丝<char=05>。 `},Id_DisplayTextPerState_166:{en:`Yes, with Nelly <char=03> and the girls<char=05>,<char=20> we are embarking on a rerun of <i> Fame</i>! Four beautiful and talented girls like us,  it has to be a hit! <i>I'm gonna live forever</i>...`,zh:`对，我跟奈莉<char=03>还有另外两个女生<char=05><char=20>将会重演<i>名扬四海</i>！我们这四名才华横溢的妙龄少女，一定会大红大紫！<i>我将永生</i>……`},Id_DisplayTextPerState_167:{en:`Yes, that looks like a piece of the ropes that are used to hoist or lower the backdrops. One of them actually almost fell on me during the last rehearsal! I could have died, you know!`,zh:`对，这根绳子用来把背景幕升起或降下，你知道吗？上次彩排时，有一块差点掉下来砸死我了！`},Id_DisplayTextPerState_168:{en:`I don't know her password.`,zh:`我不知道密码。`},Id_DisplayTextPerState_169:{en:`Keep that away from me! You'll end up hurting someone! We're acting here, we're not actually trying to kill each other!`,zh:`把那个拿远一点！你会伤害到人！我们在这里是演戏，不是真的要杀死对方。`},Id_DisplayTextPerState_170:{en:`That killer running amok... It creeps me out. I don't feel safe.`,zh:`凶手还在逞凶……多可怕，我很不安。`},Id_DisplayTextPerState_171:{en:`But why is there a picture of our agent? Did she have a relationship with him?`,zh:`为什么里面是我们经纪人的照片？他们有一腿吗？`},Id_DisplayTextPerState_172:{en:`In our play, there is also a man with the rose, a character with a passion for women, who refuses to let them leave him.`,zh:`这部剧作里也有一个玫瑰男的角色，对女性有种狂热，把她们留在自己身边，不让她们离开。`},Id_DisplayText_Default_25:{en:`What do you want me to do with this?`,zh:`这个跟我有关吗？`},Id_DisplayTextPerState_173:{en:`That's one of the jackets worn by the cricket team... It must be Sean's <char=45> or Marc's<char=50>.`,zh:`这是一件板球队球衣……应该属于西恩<char=45>或马克<char=50>。`},Id_DisplayTextPerState_174:{en:`How dreadful! You should bring that to a qualified person!`,zh:`真可怕！你应该拿给相关专业的人看！`},Id_DisplayTextPerState_175:{en:`Oh no, thank you, that's not my thing! You should see Daisy<char=05>, instead...`,zh:`不，谢谢你，我不碰这类东西的！你该问一下黛丝<char=05>……`},Id_DisplayTextPerState_176:{en:`We had started to print flyers with the girls<char=05>,<char=02>,<char=03> for a production of <i> Fame</i>. But Lily <char=02> is a real pest, who will do absolutely anything to take the lead...<i> I feel it coming together</i>...`,zh:`我们印制了传单，宣传我跟其他女生<char=05><char=02><char=03>一同演出的音乐剧<i>名扬四海</i>。不过莉莉<char=02>真是讨厌，她为了夺得主角位置，什么事情都做得出……<i>我觉得她开始有动作了</i>……`},Id_DisplayTextPerState_177:{en:`Daisy <char=05> was the one who was blackmailing Nelly <char=03>! She was jealous and wanted to oust her from the agency and even the group. Or maybe she had another reason.`,zh:`黛丝<char=05>就是勒索奈莉<char=03>的人。她嫉妒奈莉，所以想把她排挤出公司甚至我们的组合。也许她这么做有其他原因。`},Id_DisplayTextPerState_178:{en:`Makes me shudder in horror. That's what the victims where strangled with?`,zh:`看到就让我打冷颤。就是用这勒死人吗？`},Id_DisplayTextPerState_179:{en:`This is of no use to me.`,zh:`与我无关。`},Id_DisplayTextPerState_180:{en:`Oh my God! There's still blood on it!`,zh:`天！上面还有血！`},Id_DisplayTextPerState_181:{en:`I didn't know Nelly <char=03> was that terrified by the killer with the rose...`,zh:`我都没想到奈莉<char=03>这么害怕玫瑰杀手……`},Id_DisplayTextPerState_182:{en:`And what's that picture of Mike Damon<char=55> in her bag? What was going on between them? What a snake! That's why she always auditioned before me!`,zh:`为什么这张麦克·戴蒙<char=55>的照片在她的手袋里？他们之间有什么事？真阴险！所以她总是在我之前获得甄选机会！`},Id_DisplayTextPerState_183:{en:`Are you offering me a flower because my name is Jasmine?`,zh:`因为我是名花，所以送花给我吗？`},Id_DisplayText_Default_26:{en:`What am I supposed to do with this?`,zh:`这跟我有关吗？`},Id_DisplayTextPerState_184:{en:`Hey! That's my jacket! I thought Nelly <char=03> had borrowed it from me. Where did you find it?`,zh:`喂！那是我的夹克！我以为是奈莉<char=03>借去了。你在哪里找到的？`},Id_DisplayTextPerState_185:{en:`Oh sh...! Nelly's <char=03> finger! Did the killer kidnap her? She's a pretty girl, that would make sense...`,zh:`该死的……奈莉<char=03>的手指！杀手绑架了她吗？她那么漂亮，难怪犯人看上她……`},Id_DisplayTextPerState_186:{en:`Ok... Sometimes, Jodie<char=54> supplies me, but it's just to party! She hangs around in a squat near East End<loc=I>.`,zh:`好吧……有时候祖迪<char=54>给我一些药物，但只是用来开派对！她在东区<loc=I>一幢非法占用居所附近出没。`},Id_DisplayTextPerState_187:{en:`Yes, I know them well enough, the four girls: Nelly <char=03>, Daisy <char=05>, Lily <char=02> and Jasmine <char=20>. They are rather attractive on this poster, aren't they?`,zh:`对，我很熟悉这四个女生：奈莉<char=03>、黛丝<char=05>、莉莉<char=02>和雅仕敏<char=20>。这张海报显得每人都美丽非凡，对吧。`},Id_DisplayTextPerState_188:{en:`Okay, I happened to send her kinda hot messages while I was with Nelly <char=03>... But I'm a good person, I made sure Nelly wouldn't know about it so she wouldn't be hurt.`,zh:`好吧，我跟奈莉<char=03>在一起的时候，曾经给黛丝寄过调情短讯……不过我是个好人，我确定奈莉不知道，所以她不会受伤。`},Id_DisplayTextPerState_189:{en:`Nah, we don't use this for cricket.`,zh:`这在打板球时用不上。`},Id_DisplayTextPerState_190:{en:`Yeah I know, I didn't send her many messages. Maybe that's why she was a bit paranoid. But I liked her anyway.`,zh:`对，我知道我不常发讯息给她，也许让她有点多疑，不过我还是喜欢她的。`},Id_DisplayTextPerState_191:{en:`I never touch that stuff.`,zh:`我没碰过这东西。`},Id_DisplayTextPerState_192:{en:`I hope the killer will be arrested.`,zh:`希望尽快抓住犯人。`},Id_DisplayTextPerState_193:{en:`Hey! There should be a picture of me there!`,zh:`嘿！那里应该有我的照片！`},Id_DisplayTextPerState_194:{en:`I am not the one who gave her that rose.`,zh:`我不知道谁送她玫瑰。`},Id_DisplayText_Default_27:{en:`This is not one of the theatre's props.`,zh:`这不是这个剧场的道具。`},Id_DisplayTextPerState_195:{en:`Oh no... That's a real one? I wonder how it feels to sever a finger... And why the left ring finger in particular?`,zh:`天哪……真的手指？我不知道被割下手指是怎么样的感觉……而且为什么是左手无名指？`},Id_DisplayTextPerState_196:{en:`The girls<char=05>,<char=02>,<char=20> were planning to stage a musical based on <i>Fame</i>. Lily<char=02> was particularly determined to have the lead role.`,zh:`这些女孩<char=05><char=02><char=20>将要登台演出音乐剧<i>名扬四海</i>。莉莉<char=02>摩拳擦掌要夺得主角位置。`},Id_DisplayTextPerState_197:{en:`Sure, I know this kind of rope, it’s frequently used to hang theater decoration.`,zh:`我当然知道，这种绳子通常用来吊起剧场布景。`},Id_DisplayTextPerState_198:{en:`Be careful, you could hurt someone.`,zh:`小心伤到人。`},Id_DisplayTextPerState_199:{en:`Interesting. Do you think it could help me as further research for my role?`,zh:`有趣。你觉得这有助我投入角色吗？`},Id_DisplayTextPerState_200:{en:`Could I keep it? It inspires me...`,zh:`我可以保留它吗？它能给我灵感……`},Id_DisplayText_Default_28:{en:`Is it easy to resell?`,zh:`这容易转手吗？`},Id_DisplayTextPerState_201:{en:`That's one of the team's jackets, looks like Marc's<char=50>.`,zh:`这是一件板球队球衣……看来属于马克<char=50>。`},Id_DisplayTextPerState_202:{en:`Seriously, keep that away from me!`,zh:`我说真的，拿开它！`},Id_DisplayTextPerState_203:{en:`I am completely broke, so how could I afford that?`,zh:`我一穷二白，怎买得起？`},Id_DisplayTextPerState_204:{en:`The girls<char=03><char=05>,<char=02>,<char=20> were fully involved in that musical project. They could have made a lot of money if it worked out!`,zh:`这些女孩<char=03><char=05><char=02><char=20>全心投入音乐剧的演出，要是成功便可以赚大钱！`},Id_DisplayTextPerState_205:{en:`What do you want me to do with this?`,zh:`这个跟我有关吗？`},Id_DisplayTextPerState_206:{en:`I have got nothing to do with this. It is not a professional knife.`,zh:`这跟我无关，又不是球具。`},Id_DisplayTextPerState_207:{en:`That killer running amok, it's downright freaky. It scares off female customers at night and people don't tip as much.`,zh:`杀手正逞凶，让人胆跳心惊，女顾客吓得晚上不敢光临，小费也少了许多。`},Id_DisplayTextPerState_208:{en:`Isn't yellow the colour for cuckolds?`,zh:`黄色不是不忠的颜色吗？`},Id_DisplayText_Default_29:{en:`I have no use for this.`,zh:`我不需要用到这个。`},Id_DisplayTextPerState_209:{en:`There is no severed finger in my play.`,zh:`我的剧作中没有断指。`},Id_DisplayTextPerState_210:{en:`I very much doubt that my actors would have anything to do with this.`,zh:`我不认为这跟我的演员有任何一丝关系。`},Id_DisplayTextPerState_211:{en:`What? On top of everything, that little know-it-all planned to stage a musical? I should have sacked her from the theatre company. She doesn't deserve to have the lead role if she's only seeking the limelight.`,zh:`什么？那无知少女打算演出音乐剧？我真应该把她从剧场开除掉。一心只想出风头的人不配当主角。`},Id_DisplayTextPerState_212:{en:`Well, I really don't care about girl drama...`,zh:`我对女孩之间的吵吵闹闹不屑一顾。`},Id_DisplayTextPerState_213:{en:`Oh... that's the piece of guide rope that was stolen! A backdrop almost fell on my supporting role! Where did you find it?`,zh:`噢……有人偷走了我们的绳子！之前背景幕差点掉到一名配角头上！你在哪里发现的？`},Id_DisplayTextPerState_214:{en:`Don't count on me to nose around in my actors' private lives.`,zh:`女演员的私生活，你自己去找吧，别扯上我。`},Id_DisplayTextPerState_215:{en:`I have the same in my kitchen, without the blood.`,zh:`我厨房里也有这把，但没沾血。`},Id_DisplayTextPerState_216:{en:`I have to admit that my play is greatly inspired by the story of the killer with the rose. The obsessive character of that guy strikes me, and his signature is particularly remarkable. @The rose, allegory of love and passion, was also used to honor the dead in ancient times. `,zh:`我必须承认新剧很大部分灵感来自这名玫瑰杀手，他着魔般的行径震撼了我，而且留下身份的方式与众不同。@玫瑰使人联想到爱和热情，在古代用来崇敬死者。`},Id_DisplayTextPerState_217:{en:`I didn't know that the rose left by the killer was yellow... In theatre, you know, everything is a symbol. In this case, yellow embodies infidelity and betrayal. `,zh:`我不知道凶手留下黄色玫瑰……你要知道剧作中任何东西都有象征意味，而黄色代表不忠与背叛。`},Id_DisplayText_Default_30:{en:`I don't have anything to do with that!`,zh:`这跟我无关！`},Id_DisplayTextPerState_218:{en:`I think this belongs to Nelly's <char=50> boyfriend. Sometimes she takes it to wear it, she says she likes its smell. A girl in love, you know.`,zh:`我猜这属于奈莉的男朋友<char=50>。她有时会穿上它，说喜欢那气味。坠入爱河的少女啊...。`},Id_DisplayTextPerState_219:{en:`I have seen pretty much everything, but all the same, you don't have to show this to me!`,zh:`我见过许多事情，但这东西还是不用给我看！`},Id_DisplayTextPerState_220:{en:`I confess, I've been dealing a bit to get by since I was 15. But I never hurt anyone! `,zh:`我发誓，虽然从十五岁起以东西谋生，但我从未伤害任何人！`},Id_DisplayTextPerState_221:{en:`Yeah, well... Girls who announce that they're going to do a catwalk show, act, sing and dance... Good for them.`,zh:`诶，对……这些女生宣布将会走伸展台和歌舞表演……很适合她们。`},Id_DisplayTextPerState_222:{en:`Erm... yeah... maybe I am the one who talked to Daisy <char=05> about Nelly's past, that time we took speed together...`,zh:`嗯……对……也许是我跟黛丝<char=05>说起奈莉的过去，那时候我们一起用了点冰毒.`},Id_DisplayTextPerState_223:{en:`Nelly <char=03> couldn't bear not knowing the father who had abandoned her at birth, assuming that he was even aware of her existence, considering her nutty mother... She told me she had found him at last.`,zh:`奈莉<char=03>接受不了出生没多久就被生父遗弃，一直自以为父亲还在留意她，并关心患精神病的母亲……奈莉告诉我终于找到生父了。`},Id_DisplayTextPerState_224:{en:`Yeah, that's Nelly's <char=03> mother on the picture.`,zh:`对，照片里是奈莉<char=03>的母亲。`},Id_DisplayTextPerState_225:{en:`I've never been offered flowers! But as you know, <i>life is not a bed of roses</i>...`,zh:`我从未收过花！不过你也知道<i>花无百日红</i>……`},Id_DisplayText_Default_31:{en:`So what?`,zh:`所以？`},Id_DisplayTextPerState_226:{en:`Hey! I recognise it! It's the cricket team's jacket, Nelly <char=03> used to wear it a lot.`,zh:`嘿！我认得！它是板球队夹克，奈莉<char=03>常常穿。`},Id_DisplayTextPerState_227:{en:`Oh no, that can't be true... That's Nelly's <char=03> finger!`,zh:`我的天……这不是真的……奈莉<char=03>的手指！`},Id_DisplayTextPerState_228:{en:`I don't touch that stuff, and neither does Nelly <char=03>.`,zh:`我不碰这些的，奈莉<char=03>也不会。`},Id_DisplayTextPerState_229:{en:`My Nelly <char=03> was going to become a star all right!`,zh:`我的奈莉<char=03>快要当明星了！`},Id_DisplayTextPerState_230:{en:`Would you leave it to me? I would like to have some pictures of her...`,zh:`你会把这给我吗？我想要更多她的照片……`},Id_DisplayTextPerState_231:{en:`Personally, I think this killer is obsessed with talented women.`,zh:`我看得出这杀手对才华横溢的女性十分着迷。`},Id_DisplayTextPerState_232:{en:`No, I would have liked to leave her a red rose instead.`,zh:`不，我会送上红色玫瑰。`},Id_DisplayText_Default_32:{en:`I really don't see what I could do with this.`,zh:`我不知道能告诉你什么。`},Id_DisplayTextPerState_233:{en:`Such a... thing in my agency. It's embarrassing.`,zh:`真是……我的公司怎么会发生这么尴尬的事？`},Id_DisplayTextPerState_234:{en:`Sadly, it is pretty common in modeling circles... I know some girls go to a squat in the East End<loc=I> to get their kicks.`,zh:`可怜的是模特儿圈子里，这是很稀松……我知道有些女孩会到东区一幢非法占用居所<loc=I>拿货。`},Id_DisplayTextPerState_235:{en:`Yeah, as I see it, the girls are fiercely ambitious and they tend to neglect their careers...`,zh:`对，我看得出这些女孩野心澎湃，甚至放弃自己的事业……`},Id_DisplayTextPerState_236:{en:`I won't touch this. Bring it to your experts and solve this murder!`,zh:`我不会碰它。拿给专家破案吧！`},Id_DisplayTextPerState_238:{en:`We all have kitchen knives like that at home.`,zh:`每家每户都有的。`},Id_DisplayTextPerState_239:{en:`That killer is the talk of the town. How could I be unaware of his existence? I hope you will arrest him soon.`,zh:`这杀手是热门话题，我哪会没听过？请你尽快逮捕他。`},Id_DisplayTextPerState_240:{en:`It was just over 20 years ago... I had an affair with that woman but it didn't last. I don't know what became of her after that. @But I can tell you that she's the reason why I have this face today! She was a tease, all men were hovering around her.`,zh:`那是超过二十年前的事……我跟女人有过短暂关系，也不知道之后她变成怎样了。@但我能告诉你，我的脸变成这个样子，全怪她！她很风骚，身边总是有男人围著。`},Id_DisplayTextPerState_241:{en:`I wouldn't give this to my models. People would talk...`,zh:`我不会送这给我的模特儿，免得大家说闲语。`},Id_DisplayTextPerState_242:{en:`What a nasty little snake! So she was the one who was blackmailing me pretending to be my hidden daughter! When I think that I gave her money to try and get rid of her...`,zh:`真恶毒！所以就是她勒索我，假装是我的私生女吗！我还打算付钱摆脱她……`},Id_DisplayTextPerState_243:{en:`What a tragedy... and how brutal... If all the girls disappear like that, I'll go out of business!`,zh:`悲剧……可怕……要是全部女孩都这样失踪，会毁掉我的事业！`},Id_DisplayTextPerState_244:{en:`That can't be true... It's the third one! Someone is after me, for sure.`,zh:`这不是真的……第三人！肯定有人想搞垮我！`},Id_DisplayTextPerState_245:{en:`All I can do now is shut down the agency... What will people think?`,zh:`我惟有关掉经纪公司了……人们会怎么想？`},Id_DisplayTextPerState_246:{en:`No that can't be true! I bet you she had found the trail of that killer who fascinated her, and it proved fatal to her!`,zh:`这不是真的！我肯定她发现了凶手的踪迹，最终惨遭毒手！`},Id_DisplayTextPerState_247:{en:`That can't be true... That being said, that's one less rival, at least.`,zh:`这不是真的……话说回来，起码少了一个竞争对手。`},Id_DisplayTextPerState_248:{en:`Her too? It's the killer with the rose, I'm sure of it! Or maybe it's a copycat...`,zh:`她也遇害？我肯定是玫瑰杀手！或者只是模仿……`},Id_DisplayTextPerState_249:{en:`Lily? Dead? No... I have to confess that I knew her a bit more intimately than I was saying... Please don't tell Sean <char=45>! But how could I resist? They are all real knockouts...`,zh:`莉莉死了？这不是真的……我得坦承我俩之间比之前告诉你的其实更加亲密……请不要告诉西恩<char=45>！但我抗拒不了，她们全都是尤物……`},Id_DisplayTextPerState_250:{en:`Daisy? Dead? She was so full of life... I may have sinned with her a couple of times, but keep it quiet, I value my reputation.`,zh:`黛丝死了？她是那么有活力的人……我曾偷偷跟她一起几次，但请保密，我很看重名誉。`},Id_DisplayTextPerState_251:{en:`I can't believe it. Someone has to be after me! I had gone out with Jasmine too.`,zh:`我无法相信。有人针对我！我跟雅仕敏也有过关系。`},Id_DisplayTextPerState_252:{en:`Life has become tasteless after Daisy's death, so one more or one less, what does it matter?`,zh:`黛丝死后，生命索然无味，再多一人又如何？`},Id_DisplayTextPerState_253:{en:`What? Daisy, dead? My Daisy, are you sure?`,zh:`什么？黛丝死了？我的黛丝！你没骗我？`},Id_DisplayTextPerState_254:{en:`You are dust and to dust you shall return... Life just tastes like ashes now...`,zh:`你轻轻地走，正如你轻轻地来……人生一片漆黑……`},Id_DisplayTextPerState_255:{en:`No, it's not me! I wanted to go out with her to get the money she was likely to win with the casting, so why would I have done that?`,zh:`不，不是我做的！我还打算跟她一起分享将要到手的奖金，怎会杀死她？`},Id_DisplayTextPerState_256:{en:`Lily? I can't believe it... It's true that I was going to leave her, but I would never have killed her!`,zh:`莉莉？假的吧……的确我想跟她分手，但怎会杀死她呢？`},Id_DisplayTextPerState_257:{en:`I didn't really know her. But Marc <char=50> told me that behind her seemingly innocent ways, she was a real tiger. @ As tragic as her death is, it increases the probability of Jasmine <char=20> winning the casting and the money that goes with it.`,zh:`我不认识她，不过马克<char=50>告诉我她看似无辜，其实口蜜腹剑。@尽管她被杀是惨剧，但的确令雅仕敏<char=20>胜算更大，可以赢得奖金。`},Id_DisplayTextPerState_258:{en:`Here we go again, one less actress! That being said, I might be able to find better.`,zh:`又来了。另一位女演员！不过我也可因此找个更佳人选。`},Id_DisplayTextPerState_259:{en:`What did she die from? Not an overdose, I hope? True, I did supply speed to her on some occasions, but nothing more...`,zh:`她怎么死的？不是剂量过重吧？我的确曾向她提供冰毒，但已经停止了……`},Id_DisplayTextPerState_260:{en:`Her death is sad. Have you found my Nelly <char=03>? Is she safe?`,zh:`令人难过。你找到我的奈莉<char=03>吗？还安全吗？`},Id_DisplayTextPerState_261:{en:`Another one dead? But where is my Nelly <char=03>? Have you found her?`,zh:`又一名死者？不过奈莉<char=03>在哪里？你找到她了吗？`},Id_DisplayTextPerState_262:{en:`Another one? What about Nelly <char=03>?`,zh:`再一人？那么奈莉呢<char=03>？`},Id_LocationState_Introduction_1:{en:`You discover a lively neighbourhood full of restaurants and bars. Two very friendly young people work there <char=02><char=45>.`,zh:`你发现这社区有许多餐厅和酒吧。两名非常要好的年轻人<char=02><char=45>在这里工作。`},Id_LocationState_Introduction_2:{en:`The agency is small but welcoming. A man is sitting at his desk<char=55>. A young woman<char=05> is in the next room.`,zh:`这家经纪公司虽小却很好客。一名男人<char=55>坐在办公桌前，一名女性<char=05>在另一间房间。`},Id_LocationState_Introduction_3:{en:`You are about to get access to the missing person's studio, at last, while keeping an eye on the troublesome man.`,zh:`你终于要进去失踪者的工作室，同时盯著那个制造麻烦的男人。`},Id_LocationState_Introduction_4:{en:`The rehearsal premises are located in a building that is a bit older yet well maintained. Two men <char=42><char=31> are rehearsing a scene.`,zh:`彩排场位于一幢老旧却保养得不错的建筑物。两名男子<char=42><char=31>正在排练一幕。`},Id_LocationState_Introduction_5:{en:`You arrive at the park, where several sports teams are training. You notice in particular a young woman<char=20> who fervently supports the players.`,zh:`你来到公园，看到几队运动队伍正在练习。你还留意到一名少女<char=20>正热切地招呼运动员。`},Id_LocationState_Introduction_6:{en:`The East End neighbourhood, in the area you are in, is not necessarily very safe. A woman catches your attention <char=54>. She looks a little odd.`,zh:`你来到东区，这里并不十分安全。你留意到一名女人<char=54>看来有点突兀。`},Id_DisplayTextPerState_263:{en:`How did you find me? What do you want?`,zh:`找我什么事？想要什么？`},Id_DisplayText_Default_33:{en:`The person you are looking for is not here.`,zh:`你要找的人物不在这里。`},Id_DisplayText_Default_34:{en:`The person you are looking for is not here.`,zh:`你要找的人物不在这里。`},Id_DisplayText_Default_35:{en:`The person you are looking for is not here.`,zh:`你要找的人物不在这里。`},Id_DisplayText_Default_36:{en:`The person you are looking for is not here.`,zh:`你要找的人物不在这里。`},Id_DisplayText_Default_37:{en:`The person you are looking for is not here.`,zh:`你要找的人物不在这里。`},Id_DisplayText_Default_38:{en:`The person you are looking for is not here.`,zh:`你要找的人物不在这里。`},Id_DisplayText_Default_39:{en:`What do you expect from me? I am confused after everything that happened...`,zh:`你想要我回答什么？发生这么多事，我有点混乱……`},Id_DisplayTextPerState_264:{en:`What can I say... I took refuge here thanks to Jodie<char=54>, who agreed to hide me at the squat without asking me any questions. I had good reasons, believe me!`,zh:`我该说什么呢……谢谢祖迪<char=54>让我在这里避难，不问任何问题便同意我躲在这里。我能解释的，相信我！`},Id_DisplayTextPerState_265:{en:`It's tragic. The killer with the rose definitely did it.`,zh:`真是悲剧。凶手明显是玫瑰杀手。`},Id_DisplayTextPerState_266:{en:`It's a bloodbath...`,zh:`这是一场虐杀……`},Id_DisplayTextPerState_267:{en:`Isn't there a chance that she's next on the list?`,zh:`她不是也有机会遇害吗？`},Id_DisplayTextPerState_268:{en:`Keep your eyes off of him, that's MY man!`,zh:`别打主意！他是我的！`},Id_DisplayTextPerState_269:{en:`We met a few years ago. Things were tough at the time...`,zh:`我们几年前见过面，那时候很难熬……`},Id_DisplayTextPerState_270:{en:`I wish I'd never met that person... There's nothing more to say.`,zh:`我真希望没有遇过这人……没什么好说的。`},Id_DisplayText_Default_40:{en:`Don't you have anything better to do than to show me things you found at the flea market? Where are the police when you need them?`,zh:`你真无聊，给我看这些跳蚤市场找到的破烂吗？要你这样的警察干什么吃的？`},Id_DisplayTextPerState_271:{en:`This jacket looks like the one the boys wear for their cricket team.`,zh:`看来是其中一名板球队员的夹克。`},Id_DisplayTextPerState_272:{en:`That's definitely my finger, but I... I am not feeling well...`,zh:`这一定是我的手指，但是……我……我不舒服。`},Id_DisplayTextPerState_273:{en:`This must be Jodie's <char=54>.`,zh:`这一定是祖迪<char=54>的。`},Id_DisplayTextPerState_274:{en:`Yes, we had projects with the girls <char=05>,<char=02>,<char=20> but it's all useless now.`,zh:`对，我们四人<char=05><char=02><char=20>原本要演音乐剧，但现在没有意义了。`},Id_DisplayTextPerState_275:{en:`But... there is still blood on it...`,zh:`不过……上面还有血……`},Id_DisplayTextPerState_276:{en:`What? Are you sure it's my blood? Then it's the rope my attacker used, I have no doubt about it.`,zh:`什么？你肯定上面有我的血？那么肯定是施暴的人用的，我十分肯定。`},Id_DisplayTextPerState_277:{en:`That's my private life. It's none of your business!`,zh:`那是我的私生活，与你一点关系都没有！`},Id_DisplayTextPerState_278:{en:`So what? Everybody has a kitchen knife at home.`,zh:`怎么了？每家每户都有。`},Id_DisplayTextPerState_279:{en:`Have you found the killer? I don't even remember how I managed to escape him, I am scared to death!`,zh:`你抓到凶手了吗？我记不得怎样逃出来了。我吓得要死！`},Id_DisplayTextPerState_280:{en:`That's a picture of my mother in this bag, with who is probably... my father.`,zh:`里面有我妈妈的照片，合照的还有……大概是我的父亲。`},Id_DisplayText_Action_4:{en:`Nelly <char=03> runs away right in front of your astonished eyes!`,zh:`奈莉<char=03>惊慌地从你眼前逃走！`},Id_DisplayTextPerState_281:{en:`Nelly <char=03> is not here anymore. What's got into her? What makes it even more odd is that she obviously needs care for her cut finger...`,zh:`奈莉<char=03>不在这里了。她发生什么事了？更奇怪的是，她根本不在意被割下的手指……`},Id_DisplayTextPerState_282:{en:`Technology is my thing! What do we have here?`,zh:`科技是我的专长！有什么需要帮忙？`},Id_DisplayTextPerState_283:{en:`Technology is my thing! What do we have here?`,zh:`科技是我的专长！有什么需要帮忙？`},Id_DisplayTextPerState_284:{en:`Technology is my thing! What do we have here?`,zh:`科技是我的专长！有什么需要帮忙？`},Id_DisplayTextPerState_285:{en:`Technology is my thing! What do we have here?`,zh:`科技是我的专长！有什么需要帮忙？`},Id_DisplayTextPerState_286:{en:`Technology is my thing! What do we have here?`,zh:`科技是我的专长！有什么需要帮忙？`},Id_DisplayTextPerState_287:{en:`Technology is my thing! What do we have here?`,zh:`科技是我的专长！有什么需要帮忙？`},Id_LocationState_Introduction_7:{en:`As you arrive in front of the missing person's studio that needs to be inspected, you get your hands on a suspicious man who was trying to break into her home<char=32>.`,zh:`你来到失踪者的工作室，需要著手搜查。同时发现一名可疑男子<char=32>，试图闯进房子里。`},Id_DisplayTextPerState_288:{en:`The dead don't lie, and they never contradict me. Who is this about?`,zh:`死人不会说谎，对我揭露的都是实话。这次是谁？`},Id_DisplayTextPerState_289:{en:`The dead don't lie, and they never contradict me. Who is this about?`,zh:`死人不会说谎，对我揭露的都是实话。这次是谁？`},Id_DisplayTextPerState_290:{en:`The dead don't lie, and they never contradict me. Who is this about?`,zh:`死人不会说谎，对我揭露的都是实话。这次是谁？`},Id_DisplayTextPerState_291:{en:`The dead don't lie, and they never contradict me. Who is this about?`,zh:`死人不会说谎，对我揭露的都是实话。这次是谁？`},Id_DisplayTextPerState_292:{en:`The dead don't lie, and they never contradict me. Who is this about?`,zh:`死人不会说谎，对我揭露的都是实话。这次是谁？`},Id_DisplayTextPerState_293:{en:`The dead don't lie, and they never contradict me. Who is this about?`,zh:`死人不会说谎，对我揭露的都是实话。这次是谁？`},Id_DisplayTextPerState_294:{en:`If I can help you to better understand the intricacies of the human mind, I'd be happy to!`,zh:`如果你需要明白错综复杂的人心，我很乐意帮忙。`},Id_DisplayTextPerState_295:{en:`If I can help you to better understand the intricacies of the human mind, I'd be happy to!`,zh:`如果你需要明白错综复杂的人心，我很乐意帮忙。`},Id_DisplayTextPerState_296:{en:`If I can help you to better understand the intricacies of the human mind, I'd be happy to!`,zh:`如果你需要明白错综复杂的人心，我很乐意帮忙。`},Id_DisplayTextPerState_297:{en:`If I can help you to better understand the intricacies of the human mind, I'd be happy to!`,zh:`如果你需要明白错综复杂的人心，我很乐意帮忙。`},Id_DisplayTextPerState_298:{en:`If I can help you to better understand the intricacies of the human mind, I'd be happy to!`,zh:`如果你需要明白错综复杂的人心，我很乐意帮忙。`},Id_DisplayTextPerState_299:{en:`If I can help you to better understand the intricacies of the human mind, I'd be happy to!`,zh:`如果你需要明白错综复杂的人心，我很乐意帮忙。`},Id_DisplayTextPerState_300:{en:`Hello! What do you have for me?`,zh:`你好，请问有事吗？`},Id_DisplayTextPerState_301:{en:`Hello! What do you have for me?`,zh:`你好，请问有事吗？`},Id_DisplayTextPerState_302:{en:`Hello! What do you have for me?`,zh:`你好，请问有事吗？`},Id_DisplayTextPerState_303:{en:`Hello! What do you have for me?`,zh:`你好，请问有事吗？`},Id_DisplayTextPerState_304:{en:`Hello! What do you have for me?`,zh:`你好，请问有事吗？`},Id_DisplayTextPerState_305:{en:`Hello! What do you have for me?`,zh:`你好，请问有事吗？`},Id_DisplayTextPerState_306:{en:`The body is still warm, you should call someone competent to learn more about it.`,zh:`尸体还有余温，你应该给专业人士分析一下。`},Id_LocationState_Introduction_8:{en:`You walk through the familiar doors of the police station.`,zh:`你走过警局里多扇熟悉的门。`},Id_DisplayTextPerState_307:{en:`The killer with the rose usually leaves a white rose, that's his signature. This detail about the colour has never appeared in the press.`,zh:`玫瑰杀手最著名的是他会留下一支白色玫瑰，不过媒体从没报导过关于颜色的事情。`},Id_DisplayTextPerState_308:{en:`Hmm... That's a dirty job. This finger was coarsely severed with a fairly wide blade.`,zh:`嗯……这真令人不快。那手指是被宽刃的刀粗鲁地割下的。`},Id_DisplayTextPerState_309:{en:`I don't know which weapon the killer with the rose uses to cut his victim's finger, but this one is particularly sharp, sharper than a big kitchen knife.`,zh:`我不清楚玫瑰杀手通常用什么武器割下受害人的手指，不过这把刀特别尖，比一般的厨房刀还尖。`},Id_DisplayTextPerState_310:{en:`From what I know, the killer with the rose does not have any distinctive clothing.`,zh:`据我所知，玫瑰杀手没有这样特征明显的衣服。`},Id_DisplayTextPerState_311:{en:`The killer with the rose has the habit of severing his victims' left ring finger. A symbol of the commitment these young women withheld from him, and won't be able to give anyone anymore.`,zh:`玫瑰杀手习惯割下受害人的左手无名指，这是象征诺言的「信物」，代表那些女性不可再跟任何人立约。`},Id_DisplayTextPerState_312:{en:`Hmm... This is not part of the killer's <i>modus operandi</i>. He has enough strength to strangle his victims with his bare hands, which gives him a feeling of superiority.`,zh:`嗯……这不是玫瑰杀手的<i>惯用手法</i>。他赤手空拳就能勒死受害者，从中享受优越的快感。`},Id_DisplayTextPerState_313:{en:`Good job! Did she identify her attacker? 
Turn in your report as soon as possible.`,zh:`做得好！她认得出施暴者吗？

尽快提交报告。`},Id_DisplayTextPerState_314:{en:`How did you manage to let her slip away? I am going to send another team to help you find her.
Turn in your report as soon as possible.`,zh:`你怎么能让她溜走？我会派出另一小队帮助你找到她。

尽快提交报告。`},Id_DisplayTextPerState_315:{en:`And what are you waiting for to start investigating for real? Are you waiting for another victim?`,zh:`你究竟在等什么？等另一个人遇害吗？快点开始调查！`},Id_DisplayTextPerState_316:{en:`All of Nelly's <char=03> friends are getting themselves killed... But why?`,zh:`奈莉<char=03>所有朋友都一一被杀……但是为什么？`},Id_DisplayTextPerState_317:{en:`She's got a record for drug possession and dealing. Last time she was caught in a squat in East End<loc=I>. `,zh:`她有藏毒和贩毒记录。上次她在东区一幢非法占用居所<loc=I>被捕。 `},Id_DisplayTextPerState_318:{en:`That's typical of the killer with the rose... Have you shown it to one of our experts to learn more about it?`,zh:`这是玫瑰杀手作案方式……你给鉴识专家看过了吗？`},Id_DisplayTextPerState_319:{en:`Where did you think the nickname of the killer with the rose came from? Oh, he changed colour...`,zh:`你觉得玫瑰杀手这名字怎样得来的？噢，他换了颜色……`},Id_Item_Name_19:{en:`Agency camera`,zh:`经纪公司监视器`},Id_DisplayTextPerState_320:{en:`In a corner of the room, a camera overlooks the scene. Could its recordings be useful?`,zh:`房间的角落，有一部监视器拍到整个场面，录影内容会有用吗？`},Id_DisplayTextPerState_321:{en:`Difficult to get something useful, the picture is too pixelated and most of the scene is taking place out of shot. However, we can see that the attacker was wearing a burgundy jacket with some back embroidery.`,zh:`录影内容没有什么有用资讯，因为解析度太差，而且关键的现场在镜头外。不过我们看到施暴者身穿酒红色夹克，背后还有刺绣。`},Id_DisplayTextPerState_322:{en:`What's on the footage? I was out on a business meeting when it happened.`,zh:`拍到什么吗？事发时我正出外工作。`},Id_Character_Name_16:{en:`Killer with the rose`,zh:`玫瑰杀手`},Id_DisplayTextPerState_323:{en:`He's all yours, but make sure you shed light on this whole case.`,zh:`你可随便审问，但一定要找到本案焦点。`},Id_DisplayTextPerState_324:{en:`The typical profile of a serial killer: he is not related to his victims and the murders are repeated regularly over time.@His calm composure is just a mask concealing a man who needs to exercise his power and can't tolerate rejection. Don't trust him!`,zh:`典型的连环杀手：不认识受害者，隔一段时间定期犯案。@看似平静，内心却藏著展示权力的兽欲，容不下任何反抗！`},Id_DisplayTextPerState_325:{en:`Thank God you arrested him. I was scared of being next on the list!`,zh:`真庆幸你们抓到她了。我很害怕成为下一个目标。`},Id_DisplayTextPerState_326:{en:`You arrested him! What a relief! But... Where is Nelly <char=03>?`,zh:`终于抓到他！令人松一口气！可是……奈莉<char=03>在哪里？`},Id_DisplayTextPerState_327:{en:`So what? It's too late, my Daisy is dead...`,zh:`又如何？太迟了，我的黛丝都死了……`},Id_DisplayTextPerState_328:{en:`This arrest is such a relief! Even though it comes too late...`,zh:`逮捕了他实在令人松一口气！虽然是迟来的正义……`},Id_DisplayTextPerState_329:{en:`So he is the killer with the rose? I expected someone more... let's say, charismatic.`,zh:`他就是玫瑰杀手吗？我还以为……是个更有魅力的人。`},Id_DisplayTextPerState_330:{en:`What? It's that old grouch that attacked my Nelly <char=03> ?`,zh:`什么？就是这老不死袭击了我的奈莉<char=03>？`},Id_DisplayTextPerState_331:{en:`At last! My models are going to stop croaking one by one!`,zh:`终于啊！我的模特儿们不会再一一消失！`},Id_DisplayText_Default_41:{en:`I've got nothing to tell you!`,zh:`我无话可说！`},Id_DisplayTextPerState_332:{en:`That's a pretty prize. But I have nothing to do with this.`,zh:`是个美人，但与我无关。`},Id_DisplayTextPerState_333:{en:`What? Are you going to put all the murders on me? Think about it, I used to play with them a bit before bringing them back. I didn't use them up on the spot, that would have been a waste.`,zh:`怎么？把所有罪案都算到我头上吗？想想吧，我会跟她们先玩一玩，才送回原处。不会当场就糟蹋她们，这太浪费了。`},Id_DisplayTextPerState_334:{en:`Are you thick or something? How could I have killed her when I always enjoy them for two days before bringing them back?`,zh:`你脑子进水吗？我要跟她们先玩两天，才送回去啊。`},Id_DisplayTextPerState_335:{en:`Don't know her. Pretty little one.`,zh:`不认识。挺漂亮。`},Id_DisplayTextPerState_336:{en:`No thanks, I am not interested!`,zh:`这我没兴趣！`},Id_DisplayTextPerState_337:{en:`I'm famous, from what I've heard. I've got nothing else to tell you.`,zh:`看来我很有名。其余无可奉告。`},Id_DisplayText_Default_42:{en:`What do I care?`,zh:`喔是吗？`},Id_DisplayTextPerState_338:{en:`That's not my size. It's obvious, isn't it?`,zh:`看看就知道我穿不下。`},Id_DisplayTextPerState_339:{en:`Yep, I used to cut their ring finger. That way, if I couldn't put a ring on their finger, then nobody could!`,zh:`对，我会割下她们的无名指。那么即使我不能给她们戴戒指，谁也不能！`},Id_DisplayTextPerState_340:{en:`So you really think I needed that to squeeze their little birds' necks until they busted a vein?`,zh:`你真的以为我得用这东西才能扯紧她们那纤细的的鸟颈，直到血管爆裂吗？`},Id_DisplayTextPerState_341:{en:`Oh no, mine was much sharper.`,zh:`不对不对，我的可尖得多。`},Id_DisplayTextPerState_342:{en:`Hehe... I'm famous, right?`,zh:`嘻嘻，我很出名吧。`},Id_DisplayTextPerState_343:{en:`Honestly, do you really believe it's someone my size on the screen? Even with that rotten image it's obvious!`,zh:`老实说，你真的以为里面的人身形跟我一样吗？盲人也看得出不像！`},Id_DisplayTextPerState_344:{en:`Yellow is not my color, you should know that, dear experts, shouldn't you? Unless you are just amateurs?`,zh:`拜托！你是专家，该晓得我不用黄色吧！难道说你只是菜鸟？`},Id_DisplayTextPerState_345:{en:`Let me make a phone call, I have friend of mine, a shrink, who owes me a favor.@Here goes: as a teenager, Nelly <char=03> was committed because of her suicidal tendencies, but that's not all.@She was a danger not only to herself, but also to others, as her extreme possessiveness pushed her to manipulate her loved ones until she made their lives unbearable.`,zh:`让我拨一通电话，问一问人，那人欠我人情。@查到了，奈莉<char=03>在青少年时期确诊自杀倾向，不过还没完。@她不但危害自己，还危及他人，因为她的占有欲极强，试图用尽一切方法操控心爱的人，直到对方忍无可忍。`},Id_LocationState_Introduction_9:{en:`You meet detective Henry<char=37> and his team, who have taken over the crime scene and are interrogating a distressed young man <char=45>.`,zh:`你与亨利警探<char=37>和他的小队会合了，当时他封锁了现场，正在盘问一名悲痛的年轻男子<char=45>。`},Id_LocationState_Introduction_10:{en:`The East End neighbourhood, in the area you are in, is not necessarily very safe. A woman catches your attention <char=54>. She looks a little odd.`,zh:`你来到东区，这里并不十分安全。你留意到一名女人<char=54>看来有点突兀。`},Id_DisplayTextPerState_346:{en:`I know that Nelly <char=03> had other connections outside of her model friends, with unsavory characters like that Jodie <char=54>.`,zh:`我知道奈莉<char=03>除了认识模特儿朋友，在外面还有一些交情，例如声名不怎么样的祖迪<char=54>。`},Id_LocationState_Introduction_11:{en:`You enter the police station. The killer with the rose<char=33> can be interrogated here.`,zh:`你进入警局，里面正盘问玫瑰杀手<char=33>。`},Id_DisplayText_Action_3:{en:`<i>You are receiving a phone call from the Chief Officer</i>: What on earth are you doing? Nelly's third friend, Jasmine Blue<char=20>, has also been murdered! I am expecting your report immediately! In 30 minutes, it will be the end for your team.`,zh:`<i>你接到总警官来电</i>：你他马的在混什么？奈莉第三名朋友雅仕敏·白露<char=20>也被谋杀了！三十分钟内立即汇报！不然整队都滚回家。`},Id_Ending_Question_5:{en:`Who is responsible for Nelly Flower's disappearance<char=03>?`,zh:`谁导致奈莉·弗萝娃<char=03>失踪？`},Id_Ending_Question_6:{en:`Who killed the models?`,zh:`谁杀死模特儿？`},Id_Ending_Question_7:{en:`Why were the girls killed?`,zh:`为什么女生们被杀？`},Id_Ending_Question_8:{en:`What element allowed the copycat to pose as the killer?`,zh:`凶手用什么模仿连环杀手？`},Id_Ending_Question_9:{en:`How were the girls killed?`,zh:`女生怎样被杀？`},Id_LocationState_Introduction_22:{en:`The neighbourhood is too big, you don't know what you should be looking for.`,zh:`这社区太大了，你不知道目的地在哪里。`},Id_DisplayTextPerState_347:{en:`It looks like this Daisy was a fierce manipulator. Especially if she was able to access a confidential medical record. But I am more worried about Nelly's <char=03> very unstable personality. @As a teenager, she was committed because of her suicidal tendencies, but that's not all.@She was a danger not only to herself, but also to others, as her extreme possessiveness pushed her to manipulate her loved ones until she made their lives unbearable.`,zh:`看来黛丝有强烈的操控欲，尤其是她有方法察看机密医疗纪录。不过我更担心奈莉<char=03>十分不稳定的性格。她在青少年时期确诊自杀倾向，不仅如此。@她不但危害自己，还危及他人，因为她的占有欲极强，试图用尽一切方法操控心爱的人，直到对方忍无可忍。`},Id_DisplayTextPerState_348:{en:`So that nasty little brat is the one who dug up my past! It's true, I went through difficult times, but when I left the asylum, I was healed. That's harassment!`,zh:`就是那婊子在挖我的往事吗！没错，我曾经过得很痛苦，不过离开精神病院时已经痊愈。这是在揭我的疮疤！`},Id_DisplayTextPerState_349:{en:`Nelly, just out of the asylum? I knew she was weird! She was extremely jealous of her boyfriend <char=50>, a real fury!`,zh:`奈莉离开精神病院没多久吗？我就觉得她很怪异！她对男朋友<char=50>身边的人极度妒忌！没有理智的那种`},Id_DisplayTextPerState_350:{en:`I have to admit that Nelly <char=03> was extremely jealous of her boyfriend <char=50>, a real fury capable of anything!`,zh:`坦白说奈莉<char=03>对男朋友<char=50>身边的人感到极度妒忌，什么事情也做得出！`},Id_DisplayTextPerState_351:{en:`Ah yeah... That's tough! That's why she kept picking on me, going crazy every time I talked to another girl. A real maniac!`,zh:`原来……那可不好受！所以她对我吹毛求疵。每次看到我跟另一个女孩说话就发疯！`},Id_DisplayTextPerState_352:{en:`Daisy... I didn't get a chance to tell her again how much I loved her...`,zh:`黛丝……已经没机会说我多么深爱她……`},Id_DisplayTextPerState_353:{en:`Daisy, blackmailing Nelly <char=03>? No way! Of course, Nelly was an unbearable hothead. I am not surprised she spent some time in an asylum.`,zh:`黛丝不可能勒索奈莉<char=03>！不过奈莉的确是疯女人，知道她进过精神病院我并不意外。`},Id_DisplayTextPerState_354:{en:`I have to say that Nelly <char=03> was a real maniac when Marc <char=50> would talk to another girl. You should have seen the tantrums she would throw...`,zh:`奈莉<char=03>知道马克<char=50>跟其他女生说话时会很疯。真该让你看看她暴怒的样子……`},Id_DisplayTextPerState_355:{en:`As teenagers, Nelly <char=03> and I were very "disturbed". She had a tendency to spy on her loved ones and emotionally blackmail them in odious ways to make sure they loved her exclusively.`,zh:`奈莉<char=03>和我在青少年时期深感「困扰」。她会用尽办法刺探爱人的行踪，用情绪勒索他们，保证自己占有对方全盘的爱。`},Id_DisplayTextPerState_356:{en:`My Nelly <char=03> was once committed in a psychiatric asylum? Hey, if I had known, I would have gone there at that time to make sure she would be only mine!`,zh:`我的奈莉<char=03>曾经进过精神病院？嘿！要是我知道，那时我就会第一时间赶过去，让她只属于我一人。`},Id_DisplayTextPerState_357:{en:`So Nelly <char=03> had a history of mental problems? If I had known, I would never have hired her! @I should have guessed it when I saw that odd girl <char=54> waiting for her at the agency, on some nights...`,zh:`你说奈莉<char=03>有心理病史？早知道我就不会聘请她！@回想某些晚上有个怪女孩<char=54>在公司前等候她，我应该猜到……`},Id_Character_Name_17:{en:`Detective Henry`,zh:`亨利警探`},Id_DisplayText_Default_43:{en:`You'd better carry out your investigation.`,zh:`请你自己调查。`},Id_DisplayTextPerState_358:{en:`A colleague I think of very highly. I suppose she is sending you?`,zh:`我非常推崇的同僚。是她指派你来调查吧。`},Id_DisplayTextPerState_359:{en:`That's the missing girl. I can't tell you more about her, you are the one investigating the case. Did you inspect the scene properly? Do you know precise details about her relationships with her loved ones?`,zh:`这就是那失踪女孩。你已经调查好一段时间，所以我没更多事情能告诉你。仔细搜查过现场吗？知道她跟情人的关系吗？`},Id_DisplayTextPerState_360:{en:`I heard about her murder... Sounds like all of Nelly's <char=03> friends are getting themselves killed!`,zh:`我知道她的命案……听说奈莉<char=03>所有朋友都一一被杀！`},Id_DisplayTextPerState_361:{en:`My team found the victim's body at her home less than an hour ago. @When we arrived, we found that the victim had apparently been strangled. The left ring finger had been severed and there was a yellow rose on the scene.`,zh:`我的小队在不到一个小时前，在死者家中发现她的尸体。@我们到场时，发现死者明显被勒死，左手无名指被割下，而且现场留下一支黄玫瑰。`},Id_DisplayTextPerState_362:{en:`It's the boyfriend of Lily Chapman <char=02>, the last victim. He doesn't seem to realize what has happened, we couldn't get anything from him.`,zh:`他是最近一名死者莉莉·察雯<char=02>的男朋友，似乎还无法接受发生了什么事，我们从他身上得不到任何资讯。`},Id_DisplayTextPerState_363:{en:`She looks familiar... Doesn't she have a record at the police station?`,zh:`她很面熟……在警局里没有档案吗？`},Id_DisplayTextPerState_364:{en:`Lily's agent. Could he be the link between Nelly <char=03>, Daisy <char=05> and Lily <char=02>? Why would he act like that?`,zh:`莉莉的经纪人。他是不是奈莉<char=03>、黛丝<char=03>和莉莉<char=02>之间的共同点？有动机吗？`},Id_DisplayTextPerState_365:{en:`That's the acting teacher of Lily <char=02> and Nelly <char=03>. He can often be found in rehearsal premises in Bloomsbury <loc=L>.`,zh:`莉莉<char=02>和奈莉<char=03>的演艺导师。通常可在布鲁姆斯伯里的彩排场<loc=L>找到他。`},Id_DisplayTextPerState_366:{en:`I don't know if he is the one who went after Lily. Something does not feel right... We should summarize the elements of his <i>modus operandi</i>.`,zh:`我不确定是他是否看上莉莉，因为我觉得有点不对劲……我们应该归纳这人的<i>惯用手法</i>。`},Id_DisplayTextPerState_367:{en:`Why does my career interest you? Solve your case first, and maybe you'll get as many medals as I have.`,zh:`你为何对我的经历感兴趣？尽快破案，也许就能获得跟我一样多的勋章。`},Id_DisplayText_Default_44:{en:`I don't know what to tell you about this...`,zh:`我不知道有什么可以告诉你……`},Id_DisplayTextPerState_368:{en:`Yes the victim's left ring finger was cut off.`,zh:`对，死者左手无名指被割下。`},Id_DisplayTextPerState_369:{en:`I don't know where you got that. That rubbish can usually be found on the East End<loc=I> side. I have an address if you want...`,zh:`我不知道你在哪里弄到的，这种垃圾在东区<loc=I>可以找到。你要地址的话我可以给你……`},Id_DisplayTextPerState_370:{en:`A piece of rope was also found on Lily Chapman's crime scene.`,zh:`莉莉·察雯的命案现场也找到这样的绳子。`},Id_DisplayTextPerState_371:{en:`You have a nice collection of articles about the killer!`,zh:`你把那杀手的报导整理得井井有条！`},Id_DisplayTextPerState_372:{en:`I can confirm that a yellow rose was placed close to Lily's body.`,zh:`没错，莉莉的尸体旁也有一支黄色玫瑰。`},Id_DisplayTextPerState_373:{en:`This garment was found on the crime scene, which is unusual. We sent it to the lab.`,zh:`案发现场找到这件衣服，这不寻常，所以送到实验室了。`},Id_Scenario_ClosedLocationDefaultMessage:{en:`This neighbourhood doesn't need to be investigated in your case.`,zh:`本案不需你调查这区。`},Id_Scenario_SameLocationDefaultMessage:{en:`You are already here.`,zh:`你已在这里。`},Id_Scenario_UnusedScanCodeMessage:{en:`This is not a code from the game.`,zh:`这不属于这游戏。`},Id_DisplayTextPerState_125:{en:`Sorry, the team has already sealed off the crime scene. I suggest that we share our notes to find out if some elements overlap.`,zh:`抱歉，案发现场已被这小队封锁。我建议我们互相交换线索，找出漏看的事情。`},Id_DisplayTextPerState_374:{en:`No knife was found on the scene but the finger was probably cut by a similar object.`,zh:`现场找不到刀，不过手指应该是被类似工具割下。`},Id_DisplayTextPerState_375:{en:`And some cops come to talk to me again... You want an autograph?`,zh:`又有警察来找我了……你需要我的自传吗？`},Id_DisplayTextPerState_377:{en:`You know, there are areas where it is unfortunately easy to get this specific type of drugs. There are a few addresses in East End <loc=I>.`,zh:`这么说，在这区其实不难拿到某些药物。在东区<loc=I>有些地方可以买到。`},Id_DisplayTextPerState_376:{en:`Okay, okay, you got me. I saw Nelly recently, she was wearing this jacket and she asked me if I could hide her for a while. You will find her here in East End.`,zh:`好吧好吧，我怕了你。最近我见过奈莉，她身穿这件夹克，问我能不能让她在这里躲一阵子。你可以在东区找到她。`},Id_DisplayTextPerState_378:{en:`Okay, okay, you got me. I saw Nelly recently, and she asked me if I could hide her for a while. You will find her here in East End.`,zh:`好吧好吧，我怕了你。最近我见过奈莉，她问我能不能让她在这里躲一阵子。你可以在东区找到她。`},Id_DisplayTextPerState_379:{en:`You can be sure that he did a good job and he will give you all the answers you need.`,zh:`他的调查十分出色，你可从他那边知道全部所需资讯。`},Id_DisplayTextPerState_380:{en:`If Nelly is still alive, find her or turn in your report, so I can arrest someone.`,zh:`如果奈莉还活著，找到她或回来报告，好让我抓人。`},Id_DisplayTextPerState_381:{en:`Harvey Marshall, our criminologist, will certainly be able to tell you more about the source of these pills.`,zh:`我们的犯罪学家哈维·马绍一定能告诉你这些药丸的来源。`},Id_DisplayTextPerState_382:{en:`If Nelly is still alive, find her or turn in your report, so I can arrest someone.`,zh:`如果奈莉还活著，找到她或回来报告，好让我抓人。`},Id_DisplayText_Default_45:{en:`I can't help you, sorry.`,zh:`抱歉，我帮不了你。`},Id_DisplayTextPerState_383:{en:`This piece of evidence will get most people to talk if they have seen Nelly recently.`,zh:`要是最近真的有人见过奈莉，这夹克可让他们无法沉默。`},Id_DisplayTextPerState_384:{en:`This piece of evidence will get most people to talk if they have seen Nelly recently.`,zh:`要是最近真的有人见过奈莉，这夹克可让他们无法沉默。`},Id_DisplayTextPerState_385:{en:`Erm... I don't know... ermmm... He's the killer with the rose? Maybe it's him. But no, I am not 100% sure.`,zh:`嗯……我不知道……嗯……他就是玫瑰杀手吗？也许就是他，但我不肯定。`},Id_DisplayTextPerState_387:{en:`Nelly's <char=03> blood is on it? It doesn't make much difference, I can't tell you where she is.`,zh:`上面有奈莉<char=03>的血？不过我还是不知道她在哪里，帮不了你。`},Id_DisplayTextPerState_388:{en:`Nelly <char=03> was wearing that jacket? It could be but I don't know where she is.`,zh:`奈莉<char=03>穿著这件夹克？也许吧，不过我还是不知道她在哪里。`},Id_DisplayTextPerState_158:{en:`Wow, Nelly's <char=03> blood. You'd better find her, because like I said, I haven't seen her in 3 days.`,zh:`哇！奈莉<char=03>的血。请你快点找到她。正如我说的，已经三天没见过她了。`},Id_DisplayTextPerState_386:{en:`Ropes are frequently used to hang theater decoration, it’s easy to get hurt with them. But you can walk around the premises, Nelly <char=03> is not here.
`,zh:`绳子经常用于吊起剧场的背景幕，而且很容易弄伤人。你可以在这个彩排场内逛一圈，奈莉<char=03>不在这。
`},Id_DisplayTextPerState_389:{en:`Nelly's <char=03> blood on this rope? For me, it's good news. It means she is alive and the rope was used to tie her up.`,zh:`绳上有奈莉<char=03>的血？这或许能说是好消息，因为这表示她还活著而且碰触过这绳子。`},Id_DisplayTextPerState_390:{en:`If Nelly was wearing this jacket, it means she is probably still alive. Unfortunately, she is not here.`,zh:`要是奈莉穿过这件夹克，很大机会表示她还活著，不幸的是她不在这里。`},Id_DisplayTextPerState_391:{en:`Oh... that's the piece of guide line that was stolen! A backdrop almost fell on me during my supporting role! If Nelly <char=03> is the one who stole it, I am almost pleased with what is happening to her.`,zh:`噢……这就是被偷走的绳子！之前背景幕还因此而差点掉到一名配角头上！要是这真的被奈莉<char=03>偷走，我很乐见她现在的遭遇。`},Id_DisplayTextPerState_392:{en:`I've never seen Nelly wearing this garment. But as you know, I haven't seen Nelly in a few days.`,zh:`我没见过奈莉穿这件夹克，不过我这几天都没见过她。`},Id_DisplayTextPerState_393:{en:`Nelly's blood, but that's GREAT. It means she is alive, doesn't it? Are you going to find her?`,zh:`奈莉的血，不过太好了！这表示她还活著吧。你会找到她吗？`},Id_DisplayTextPerState_394:{en:`That's not fashionable, I won't have one of my models wearing that here, it could damage the agency's reputation.`,zh:`这件衣服一点也不时尚，我不会允许我的模特儿穿它，以免有损公司声誉。`},Id_DisplayTextPerState_396:{en:`If this is really the jacket Nelly Flower <char=03> was wearing, then it means that she met Lily Chapman <char=02> before her death.`,zh:`如果这真的是奈莉·弗萝娃<char=03>穿过的衣服，便表示莉莉·察雯<char=02>死前跟她见过面。`},Id_DisplayText_Action_5:{en:`It's over, time is up. Time to report your findings.`,zh:`时间到。请报告。`},Id_Ending_FinalSummary_2:{en:`Congratulations, you have solved the case and saved three girls!`,zh:`恭喜，你终于破案，而且救了三名女生！`},Id_Ending_FinalSummary_3:{en:`Congratulations, you have solved the case and saved two girls!`,zh:`恭喜，你终于破案，而且救了两名女生！`},Id_Ending_FinalSummary_4:{en:`Congratulations, you have solved the case and saved one girl!`,zh:`恭喜，你终于破案，而且救了一名女生！`},Id_Ending_FinalSummary_5:{en:`Congratulations, after three unfortunate deaths, you have solved the case!`,zh:`恭喜，在三名死者无辜牺牲之后，你终于破案！`},Id_DisplayTextPerState_395:{en:`The Internet shows that he tried to plan several rather grim theatre plays. None of them was as successful as hoped.`,zh:`网路结果显示他至今为止筹备的剧作内容晦暗，而没有任何一部大红大紫。`},Id_DisplayTextPerState_397:{en:`That's the owner of a modelling agency in Camden Town <loc=E>. He is regularly looking for young and beautiful women.`,zh:`康登镇某家模特儿经纪公司<loc=E>的老板。他通常都招募年轻美女。`},Id_DisplayTextPerState_398:{en:`I go out on a business lunch and my agency becomes a crime scene!`,zh:`当时我出外午餐谈生意，回来就发现公司成了案发现场！`},Id_DisplayText_Action_6:{en:`The police station is suddenly buzzing. A man <char=33> has been arrested, and they think he's the killer with the rose.`,zh:`警局忙翻天了，因为拘捕了疑似玫瑰杀手的男人<char=33>。`},Id_DisplayTextPerState_399:{en:`I can't believe what's happening.`,zh:`我无法相信发生了这件事。`},Id_DisplayTextPerState_400:{en:`I have already seen this girl. I don't understand why Nelly <char=03> hangs out with her. A troubled girl, if you ask me, the kind of person to have a criminal record.`,zh:`我见过这女生。不明白为什么奈莉<char=03>跟她混在一起。这人麻烦多多，我认为她甚至有犯罪纪录。`},Id_DisplayTextPerState_401:{en:`It seems that this woman doesn't like the police too much. She was evicted several times from a squat in the East End <loc=I> neighborhood.`,zh:`看来这女人不怎么喜欢警察。她曾被屡次逐出东区<loc=I>社区。`},Id_DisplayTextPerState_402:{en:`This can surely be what was used to kill Daisy Austen <char=05>`,zh:`我能断定这是杀害黛丝·奥斯汀<char=05>的凶器。`},Id_DisplayTextPerState_403:{en:`Blood from the body to the knife... `,zh:`刀上血迹来自尸体……`},Id_LocationState_Introduction_13:{en:`The park is closed at this hour. No one is here.`,zh:`公园已经关闭，里面空无一人。`},Id_DisplayText_Default_46:{en:`There is no object from this category here.`,zh:`这里没有物品符合这个类别。`},Id_DisplayText_Default_47:{en:`There is no object from this category here.`,zh:`这里没有物品符合这个类别。`},Id_DisplayText_Default_48:{en:`There is no object from this category here.`,zh:`这里没有物品符合这个类别。`},Id_DisplayText_Default_49:{en:`There is no object from this category here.`,zh:`这里没有物品符合这个类别。`},Id_DisplayText_Default_50:{en:`There is no object from this category here.`,zh:`这里没有物品符合这个类别。`}};export{e as t};